INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Kunning qorong‘i vaqtida, sun’iy yoritilmagan yo‘llarda yoki yetarli ko‘rinmaslik sharoitida yonmaydigan orqa gabarit chiroqlari bilan to‘xtab turish yoki ta’mirlash joyiga borishga ruxsat beriladimi?','Разрешается ли стоянка или движение до места ремонта с неработающими задними габаритными огнями в тёмное время суток, на неосвещённых дорогах или в условиях недостаточной видимости?','Куннинг қоронғи вақтида, сунъий ёритилмаган йўлларда ёки этарли кўринмаслик шароитида ёнмайдиган орқа габарит чироқлари билан тўхтаб туриш ёки таъмирлаш жойига боришга рухсат бериладими?','Ташқи ёритиш асбобларидан фойдаланиш',NULL,NULL,NULL,NULL,'ptest',2,15);
