INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat etiladi','Разрешается','Рухсат этилади',0),(@qid,'Yo\'lning qatnov qismi chetiga to\'g\'ri burchak ostida, uning ikkala tomoni yaxshi ko\'rinib turadigan, ko\'rinish masofasida o\'tish joyi yoki chorraha bo\'lmasa, ajratuvchi bo\'laksiz va to\'siqsiz yo\'llarda kesib o\'tish ruxsat etiladi','Разрешается переходить проезжую часть под прямым углом к её краю, на участках дороги с хорошей видимостью в обе стороны, при отсутствии в пределах видимости пешеходного перехода или перекрёстка, на дорогах без разделительной полосы и без ограждений.','Йўлнинг қатнов қисми четига тўғри бурчак остида, унинг иккала томони яхши кўриниб турадиган, кўриниш масофасида ўтиш жойи ёки чорраҳа бўлмаса, ажратувчи бўлаксиз ва тўсиқсиз йўлларда кесиб ўтиш рухсат этилади',1),(@qid,'Taqiqlanadi','Запрещается','Таъқиқланади',0);
