INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yurgizgich o\'chib qoladi','Двигатель заглохнет','Юргизгич ўчиб қолади',0),(@qid,'Ulagich detallarining yemirilishi ortadi','Увеличится износ деталей сцепления','Улагич деталларининг емирилиши ортади',0),(@qid,'Yetakchi g\'ildiraklar o\'rnidan jilmay aylanadi','Ведущие колеса будут пробуксовывать','Етакчи ғилдираклар ўрнидан жилмай айланади',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Ushbu yo\'l belgisi qo\'shimcha axborot belgisi bilan nimani bildiradi?','Этот дорожный знак вместе с дополнительной информационной табличкой означает:','Ушбу йўл белгиси қўшимча ахборот белгиси билан нимани билдиради?','Қўшимча ахборот белгилари','pt_ae71bf099f247880.webp',NULL,NULL,NULL,'ptest',4,8);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat etilgan to\'la vazni 3,5 t dan ortiq transport vositalarining to\'xtab turish joyi ko\'rsatkich qatnov qismining chetida baland to\'siq, toshi borligini bildiradi','Место стоянки транспортных средств с разрешенной максимальной массой более 3,5 т. Табличка указывает, что у края проезжей части высокий бордюрный камень','Рухсат этилган тўла вазни 3,5 т дан ортиқ транспорт воситаларининг тўхтаб туриш жойи кўрсаткич қатнов қисмининг четида баланд тўсиқ, тоши борлигини билдиради',0),(@qid,'Transport vositalarining to\'xtab turish joyiga avtomobilni ko\'rsatilgan usulda qo\'yish taqiqlanadi','Место стоянки транспортных средств; способ постановки автомобиля; указанный на табличке запрещается','Транспорт воситаларининг тўхтаб туриш жойига автомобилни кўрсатилган усулда қўйиш тақиқланади',0),(@qid,'Engil avtomobillar va mototsikllarni to‘xtab turishga qo‘yish joyi va usuli','Место и способ постановки легковых автомобилей и мотоциклов на стоянке','Енгил автомобиллар ва мотоциклларни тўхтаб туришга қўйиш жойи ва усули',1);
