INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Oldida transport vositasi to\'xtab turgan tartibga solinmaydigan piyodalar o\'tish joyiga yaqinlashib kelmoqdasiz, Siz nima qilishingiz kerak?','Вы приближаетесь к нерегулируемому пешеходному переходу; перед которым остановилось транспортное средство. Вы должны:','Oлдида транспорт воситаси тўхтаб турган тартибга солинмайдиган пиёдалар ўтиш жойига яқинлашиб келмоқдасиз, Сиз нима қилишингиз керак?','Пиёдаларнинг ўтиш жойлари ва йўналишли транспорт воситаларининг бекатлари',NULL,NULL,NULL,NULL,'ptest',4,10);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Piyodalar o\'tish joyidan o\'tish','Проехать пешеходный переход безостановочно','Пиёдалар ўтиш жойидан ўтиш',0),(@qid,'Piyodalar o\'tish joyidan to\'xtamasdan o\'tish, lekin alohida ehtiyotkorlik bilan','Проехать пешеходный переход безостановочно, но с особой осторожностью','Пиёдалар ўтиш жойидан тўхтамасдан ўтиш, лекин алоҳида эҳтиёткорлик билан',0),(@qid,'Harakatni davom ettirish, lekin to\'xtab turgan transport vositasi oldida piyodalar yo\'qligiga ishonch hosil qilgan holda','Продолжить движение, лишь убедившись, что перед остановившимся транспортным средством нет пешеходов','Ҳаракатни давом эттириш, лекин тўхтаб турган транспорт воситаси олдида пиёдалар йўқлигига ишонч ҳосил қилган ҳолда',1),(@qid,'Albatta to\'xtash, piyodalar paydo bo\'lsa, ularni o\'tkazib yuborish','Обязательно остановиться. При появлении пешеходов пропустить их','Албатта тўхташ, пиёдалар пайдо бўлса, уларни ўтказиб юбориш',0);
