INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat etiladi','Разрешается','Рухсат этилади',1),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',0),(@qid,'Agar quvib o\'tilayotgan transportning tezligi 40 km/soat dan kam bo\'lsa ruxsat etiladi','Разрешается, если скорость обгоняемого меньше 40 км/ч.','Агар қувиб ўтилаётган транспортнинг тезлиги 40 км/соат дан кам бўлса рухсат этилади',0);
