INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Belgilangan yo‘nalish bo‘yicha harakatlanayotgan yo‘nalishli transport vositalarining haydovchilari piyodalar o‘tish joyidan tashqarida oq hassa bilan ishora berayotgan ko‘zi ojiz piyodalarni o‘tkazib yuborishlari kerakmi?','Должны ли водители маршрутных транспортных средств, движущихся по установленным маршрутам, пропускать слепых пешеходов, подающих сигнал белой тростью вне пешеходных переходов?','Белгиланган йўналиш бўйича ҳаракатланаётган йўналишли транспорт воситаларининг ҳайдовчилари пиёдалар ўтиш жойидан ташқарида оқ ҳасса билан ишора бераётган кўзи ожиз пиёдаларни ўтказиб юборишлари керакми?','Пиёдаларнинг ўтиш жойлари ва йўналишли транспорт воситаларининг бекатлари',NULL,NULL,NULL,NULL,'ptest',4,16);
