INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yuk enining chekka nuqtasi oldingi yoki orqa gabarit chiroqning tashqi chekkasidan 0,4 m dan ortiq chiqib tursa','Крайняя точка груза по ширине находится на расстоянии (выступает) более 0,4м от внешнего края переднего или заднего габаритного огня','Юк энининг чекка нуқтаси олдинги ёки орқа габарит чироқнинг ташқи чеккасидан 0,4 м дан ортиқ чиқиб турса',0),(@qid,'Yuk transport vositasining gabaritlaridan 1 m ortiq chiqib tursa','Груз выступает за габариты автомобиля более чем на 1 м','Юк транспорт воситасининг габаритларидан 1 м ортиқ чиқиб турса',0),(@qid,'Tashilayotgan yuk vazni shu transport vositasi uchun ishlab chiqargan korxona belgilagan kattalikdan ortiq bo\'lsa','Если вес груза больше; чем установленная норма для данного грузового автомобиля','Ташилаётган юк вазни шу транспорт воситаси учун ишлаб чиқарган корхона белгилаган катталикдан ортиқ бўлса',1),(@qid,'Barcha aytilgan hollarda','Все перечисленные случаи','Барча айтилган ҳолларда',0);
