INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Lat yegan joyni qattiq bog\'lash, 15-20 daqiqaga muz solingan xalta qo\'yish. Oyoqni yuqori ko\'tarish, tinch qo\'yish','Наложить тугую повязку на поврежденное место, на 15-20 минут приложить мешочек со льдом. Поврежденную конечность приподнять, обеспечить покой','Лат еган жойни қаттиқ боғлаш, 15-20 дақиқага муз солинган халта қўйиш. Оёқни юқори кўтариш, тинч қўйиш',1),(@qid,'Lat yegan oyoqni tarang qilib (pastdan yuqoriga) bog\'lash, singandagi kabi shina qo\'yish. Bir stakanga yarim choy qoshig\'ida ichimlik soda solib ichirish, kasalxonaga jo\'natish','Перевязать поврежденную ногу снизу на верх; поставить шину, как при переломе Дать выпить стакан чая с пищевой содой. Отправить в больницу','Лат еган оёқни таранг қилиб (пастдан юқорига) боғлаш, сингандаги каби шина қўйиш. Бир стаканга ярим чой қошиғида ичимлик сода солиб ичириш, касалхонага жўнатиш',0),(@qid,'Oyoqni yumshoq predmetga qo\'yish','Положить ногу на мягкий предмет','Оёқни юмшоқ предметга қўйиш',0);
