INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ushbu manyovr xavfsiz bo\'lishiga va harakatlanishning boshqa qatnashchilariga halaqit bermasligiga ishonch hosil qilishi','Убедиться; что данный маневр будет безопасным и не создаст помех другим участникам движения','Ушбу манёвр хавфсиз бўлишига ва ҳаракатланишнинг бошқа қатнашчиларига ҳалақит бермаслигига ишонч ҳосил қилиши',1),(@qid,'Chapga burilish haqida ogohlantirish ishorasi berishi va hech kimga halaqit bermasligi haqida ishonch xosil qilishi','Подать предупредительный сигнал левого поворота и убедиться; что никому не будет создана помеха','Чапга бурилиш ҳақида огоҳлантириш ишораси бериши ва ҳеч кимга ҳалақит бермаслиги ҳақида ишонч хосил қилиши',0),(@qid,'Aholi punktlaridan tashqarida tovush ishora berishi','Вне населенных пунктов подать звуковой сигнал','Аҳоли пунктларидпн ташқарида товуш ишора бериши',0),(@qid,'Ko\'rsatilgan barcha harakatlarni bajarishi','Выполнить все указанные действия','Кўрсатилган барча ҳаракатларни бажариши',0);
