INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Kesishadigan yo\'lda transport vositalari bo\'lmasa chorrahadan to\'xtamay o\'tishi','Если на перекрестке на месте пересечения нет транспортных средств должен проехать без остановки','Кесишадиган йўлда транспорт воситалари бўлмаса чорраҳадан тўхтамай ўтиши',0),(@qid,'Chorrahadan o\'tishda ayniqsa hushyor bo\'lishi','Должен быть осторожным при проезде через перекресток','Чорраҳадан ўтишда айниқса ҳушёр бўлиши',0),(@qid,'Kesishadigan yo\'l bo\'ylab harakatlanayotgan transport vositalariga yo\'l berish uchun, to\'xtash chizig\'ida to\'xtab, u yo\'q bo\'lsa kesib o\'tiladigan qatnov qismining chetida to\'xtashi','Уступать дорогу транспортным средствам, движущимся по пересекаемой дороге, останавливающимся у стоп-линии, а также останавливающимся у края пересекаемого участка движения, если таковой отсутствует','Кесишадиган йўл бўйлаб ҳаракатланаётган транспорт воситаларига йўл бериш учун, тўхташ чизиғида тўхтаб, у йўқ бўлса кесиб ўтиладиган қатнов қисмининг четида тўхташи',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Qaysi javobda ruxsat berilgan harakat yo‘nalishi to‘g‘ri ko‘rsatilgan?','В каком ответе правильно указано разрешенное направление движения?','Қайси жавобда рухсат берилган ҳаракат йўналиши тўғри кўрсатилган?','Ахборот-кўрсатгич белгилари','pt_c8a3bc267ed8e54c.webp',NULL,NULL,NULL,'ptest',8,3);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat orqaga burilish','Только разворот','Фақат орқага бурилиш',0),(@qid,'To\'g\'riga va orqaga burilish','Поворот направо и разворот','Тўғрига ва орқага бурилиш',0),(@qid,'Faqat to\'g\'riga','Только прямо','Фақат тўғрига',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('«To\'xtash taqiqlangan» belgisi bilan birga to\'siqning usti bo\'ylab uzluksiz sariq chiziq chizilgan joyda yo\'lovchilarni tushirishga ruxsat beriladimi?','Разрешается ли произвести высадку пассажиров в месте; где нанесена по верху бордюра сплошная желтая линия в сочетании со знаком \"Остановка запрещена\"?','«Тўхташ тақиқланган» белгиси билан бирга тўсиқнинг усти бўйлаб узлуксиз сариқ чизиқ чизилган жойда йўловчиларни туширишга рухсат бериладими?','Ётиқ чизиқлар','pt_78188a752883fc5b.webp',NULL,NULL,NULL,'ptest',8,4);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat beriladi','Разрешается','Рухсат берилади',0),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',0),(@qid,'Belgilangan yo\'nalishdagi transport vositalari yo\'q bo\'lganda ruxsat beriladi','Разрешается в отсутствии маршрутных транспортных средств.','Белгиланган йўналишдаги транспорт воситалари йўқ бўлганда рухсат берилади',0),(@qid,'Belgilangan yo\'nalishdagi transport vositalariga ruxsat beriladi','Разрешается только маршрутным транспортным средствам','Белгиланган йўналишдаги транспорт воситаларига рухсат берилади',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Tos suyaklari singanda birinchi yordam qanday ko\'rsatiladi?','Как оказать первую помощь при переломе костей таза?','Тос суяклари синганда биринчи ёрдам қандай кўрсатилади?','Биринчи тиббий ёрдам',NULL,NULL,NULL,NULL,'ptest',8,5);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Zararlangan joyni qattiq bog\'lash, shikastlanganni yarim o\'tirgan holatga keltirish','Наложить тугую повязку на место повреждения, пострадавшему придать полу сидячее положение','Зарарланган жойни қаттиқ боғлаш, шикастланганни ярим ўтирган ҳолатга келтириш',0),(@qid,'Shikastlanganni qattiq yuzaga orqasi bilan yotqizish, zararlangan joylarga qaynoq isitgich qo\'yish','Пострадавшего уложить на спину на твердую поверхность, к местам повреждения приложить горячую грелку','Шикастланганни қаттиқ юзага орқаси билан ётқизиш, зарарланган жойларга қайноқ иситгич қўйиш',0),(@qid,'Shikastlanganni qattiq tekis yuzaga yotqizish, bukilgan va ikki tomonga kerilgan tizzalarining bo\'g\'inlari ostiga g\'o\'la shaklida o\'ram qo\'yish','Пострадавшего уложить на твердую ровную жесткую поверхность, а под согнутые и разведенные коленные суставы подложить валик','Шикастланганни қаттиқ текис юзага ётқизиш, букилган ва икки томонга керилган тиззаларининг бўғинлари остига ғўла шаклида ўрам қўйиш',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Yotiq chiziqning uzluksiz sariq chizig\'i nimani bildiradi?','Что обозначает сплошная желтая линия горизонтальной разметки?','Ётиқ чизиқнинг узлуксиз сариқ чизиғи нимани билдиради?','Ётиқ чизиқлар','pt_84637cdc63c86737.webp',NULL,NULL,NULL,'ptest',8,6);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Transport vositalarining to\'xtashi taqiqlangan joyni','Место; где запрещается остановка транспортных средств','Транспорт воситаларининг тўхташи тақиқланган жойни',1),(@qid,'Belgilangan yo\'nalishli transport vositalari uchun va taksi to\'xtashiga ruxsat berilgan joyni','Место; где разрешена остановка маршрутных транспортных средств и такси','Белгиланган йўналишли транспорт воситалари учун ва такси тўхташига рухсат берилган жойни',0),(@qid,'Transport vositalarining to\'xtab turishi taqiqlangan joyni','Место; где запрещена стоянка транспортных средств','Транспорт воситаларининг тўхтаб туриши тақиқланган жойни',0);
