INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qizil; ko\'k sariq bilan bir vaqtda; yashil','Красный; синий одновременно с желтым; зеленый','Қизил; кўк сариқ билан бир вақтда; яшил',1),(@qid,'Sariq yashil bilan bir vaqtda; qizil; ko\'k','Желтый одновременно с зеленым; красный; синий','Сариқ яшил билан бир вақтда; қизил; кўк',0),(@qid,'Qizil; yashil; ko\'k sariq bilan bir vaqtda','Красный; зеленый; синий одновременно с желтым','Қизил; яшил; кўк сариқ билан бир вақтда',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Haydovchi manyovrni bajarishda burilish ko\'rsatkichlari bilan yorug\'lik ishorasini har doim berishi kerakmi?','Всегда ли водитель должен подавать световой сигнал; указателями поворота при выполнении маневра?','Ҳайдовчи манёврни бажаришда бурилиш кўрсаткичлари билан ёруғлик ишорасини ҳар доим бериши керакми?','Огоҳлантирувчи ва авария (хавф-хатар) ишоралари',NULL,NULL,NULL,NULL,'ptest',8,9);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Har doim berishi kerak','Должен всегда','Ҳар доим бериши керак',0),(@qid,'Kerak emas, agar harakatlanishning boshqa qatnashchilarini chalg\'itishi mumkin bo\'lsa','Не должен, если он может ввести в заблуждение других участников движения','Керак эмас, агар ҳаракатланишнинг бошқа қатнашчиларини чалғитиши мумкин бўлса',1),(@qid,'Kerak, zaruriy ehtiyot choralarini ko\'rgan holda','Должен, приняв необходимые меры предосторожности','Керак, зарурий эҳтиёт чораларини кўрган ҳолда',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Haydovchi o\'z joyidan ketishi yoki transport vositasini qoldirishi mumkin, agar:','Водитель может покидать свое место или оставлять транспортное средство, если:','Ҳайдовчи ўз жойидан кетиши ёки транспорт воситасини қолдириши мумкин, агар:','Тўхташ ва тўхтаб туриш',NULL,NULL,NULL,NULL,'ptest',8,10);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'U yurgizgichni o\'chirgan va avtomobilning to\'xtab turish tormoz tizimini ulagan bo\'lsa','Он выключил двигатель и включил стояночную тормозную систему','У юргизгични ўчирган ва автомобилнинг тўхтаб туриш тормоз тизимини улаган бўлса',0),(@qid,'U yurgizgichni o\'chirgan va orqaga siljib ketishga qarshi xavfsizlik buferini o\'rnatgan bo\'lsa','Он выключил двигатель и установил задний противооткатный буфер безопасности','У юргизгични ўчирган ва орқага силжиб кетишга қарши хавфсизлик буферини ўрнатган бўлса',0),(@qid,'U transport vositasining o\'z-o\'zidan harakatlanishi yoki undan haydovchi yo\'q vaqtda foydalanishga yo\'l qo\'ymaydigan zaruriy choralarni ko\'rgan bo\'lsa','Им приняты необходимые меры; исключающие самопроизвольное движение транспортного средства или использование его в отсутствие водителя','У транспорт воситасининг ўз-ўзидан ҳаракатланиши ёки ундан ҳайдовчи йўқ вақтда фойдаланишга йўл қўймайдиган зарурий чораларни кўрган бўлса',1);
