INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Qisman ortish usuli bilan avtomobilni shatakka olishda yo\'lovchilar qayerda bo\'lishlari mumkin?','Где могут находиться пассажиры при буксировке путем частичной погрузки?','Қисман ортиш усули билан автомобилни шатакка олишда йўловчилар қаерда бўлишлари мумкин?','Механик транспорт воситаларини шатакка олиш',NULL,NULL,NULL,NULL,'ptest',8,12);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Har ikki avtomobilning kabinasida','В кабине обоих автомобилей','Ҳар икки автомобилнинг кабинасида',0),(@qid,'Shatakka oluvchi avtomobilning kabinasida','В кабине буксирующего автомобиля','Шатакка олувчи автомобилнинг кабинасида',1),(@qid,'Shatakka olingan avtomobilning kabinasida','В кабине буксируемого автомобиля','Шатакка олинган автомобилнинг кабинасида',0),(@qid,'Shatakka oluvchi avtomobilning kuzovida','В кузове буксирующего автомобиля','Шатакка олувчи автомобилнинг кузовида',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Son suyagining uchdan birining pastki qismi singanda jarohatlangan odamni transportda tashish uchun taxtakach qanday qo\'yiladi?','Как наложить транспортную шину при переломе кости в нижней трети бедра?','Сон суягининг учдан бирининг пастки қисми синганда жароҳатланган одамни транспортда ташиш учун тахтакач қандай қўйилади?','Биринчи тиббий ёрдам',NULL,NULL,NULL,NULL,'ptest',8,13);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Taxtakachni sonning butun uzunligicha tos-sondan tizza bo\'g\'inigacha qo\'yib, singan joy bint bilan qattiq bog\'lab qo\'yiladi','Плотно прибинтовать шину к месту перелома, наложив ее на всю длину бедра от тазобедренного до коленного сустава','Тахтакачни соннинг бутун узунлигича тос-сондан тизза бўғинигача қўйиб, синган жой бинт билан қаттиқ боғлаб қўйилади',0),(@qid,'Ikkita taxtakach oyoqning ichki va tashqi tomonidan qo\'yiladi. Bittasini oyoq to\'pig\'idan qo\'ltiqosti chuqurigacha, ikkinchisini to\'piqdan chovgacha','Наложить две шины с внутренней и наружной стороны ноги, одну-от конца стопы до подмышечной ямки, вторую от конца стопы до паха','Иккита тахтакач оёқнинг ички ва ташқи томонидан қўйилади. Биттасини оёқ тўпиғидан қўлтиқости чуқуригача, иккинчисини тўпиқдан човгача',1),(@qid,'Ikkita taxtakach oyoqning ikki tomonidan to\'piqdan sonning yuqorigi uchdan bir qismigacha (singan joydan 15-20 sm yuqorigacha) qo\'yiladi','По обеим сторонам стопы от лодыжки до верхней трети бедра (на 15-20 см выше места перелома) кладут две доски','Иккита тахтакач оёқнинг икки томонидан тўпиқдан соннинг юқориги учдан бир қисмигача (синган жойдан 15-20 см юқоригача) қўйилади',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Chorrahadan ikkinchi bo\'lib o\'tadi:','Вторым проедет перекресток:','Чорраҳадан иккинчи бўлиб ўтади:','Тартибга солинмаган чорраҳалар асосий йўл йўналиши тўғрига','pt_7c8a80057276c0cc.webp',NULL,NULL,NULL,'ptest',8,14);
