INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Kunning qorong\'i vaqtida yoki tuman bo\'lgan sharoitda faralarning yaqinni yoritish chiroqlari','Ближний свет фар в темное время суток или в условиях тумана','Куннинг қоронғи вақтида ёки туман бўлган шароитда фараларнинг яқинни ёритиш чироқлари',0),(@qid,'Avariya yorug\'lik ishoralari, u nosoz bo\'lganda yoki bo\'lmagan hollarda uning orqa tomoniga avariya sababli to\'xtash belgisi o\'rnatilishi kerak','Аварийная сигнализация, при её отсутствии или неисправности транспортное средство должно быть обозначено знаком аварийной остановки укрепленном на нем сзади','Авария ёруғлик ишоралари, у носоз бўлганда ёки бўлмаган ҳолларда унинг орқа томонига авария сабабли тўхташ белгиси ўрнатилиши керак',1),(@qid,'Aholi punktlarida gabarit chiroqlari','Габаритные огни в населенных пунктах','Аҳоли пунктларида габарит чироқлари',0),(@qid,'Aholi punktlaridan tashqaridagi yo\'llarda istalgan yoritish chiroqlarini','Любое освещение на дорогах вне населенных пунктах','Аҳоли пунктларидан ташқаридаги йўлларда исталган ёритиш чироқларини',0);
