INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Eng past uzatmaga o\'tish, to\'xtab turish tormozi bilan tormozlash. Zarur bo\'lganda biron-bir to\'siqdan foydalanish','Перейти на низшую передачу; затормозить стояночным тормозом. При необходимости воспользоваться каким-либо препятствием','Энг паст узатмага ўтиш, тўхтаб туриш тормози билан тормозлаш. Зарур бўлганда бирон-бир тўсиқдан фойдаланиш',1),(@qid,'Ulagichni ajratish va to\'xtab turish tormozi bilan keskin tormozlash','Выключить сцепление и резко тормозить стояночным тормозом','Улагични ажратиш ва тўхтаб туриш тормози билан кескин тормозлаш',0);
