INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Hodisa sodir bo\'lgan joyda to\'xtash, guvohlarning ismi-sharifini va manzilgohini yozib olish, hodisa haqida IIO xodimlariga xabar berish, shikastlanganlarga shifokor kelguncha tibbiy yordam berish uchun choralar ko\'rish','Остановиться на месте происшествия, записать фамилии и адреса очевидцев, сообщить о случившемся в милицию, принять меры для оказания доврачебной медицинской помощи пострадавшим','Ҳодиса содир бўлган жойда тўхташ, гувоҳларнинг исми-шарифини ва манзилгоҳини ёзиб олиш, ҳодиса ҳақида ИИО ходимларига хабар бериш, шикастланганларга шифокор келгунча тиббий ёрдам бериш учун чоралар кўриш',0),(@qid,'Darhol to\'xtash va hodisa sodir bo\'lgan joyda qolish, majburiy to\'xtash yoritgichini yoqish va falokat sababi to\'xtash belgisini o\'rnatish','Немедленно остановиться и оставаться на месте происшествия, включить аварийную световую сигнализацию и выставить знак аварийной остановки','Дарҳол тўхташ ва ҳодиса содир бўлган жойда қолиш, мажбурий тўхташ ёритгичини ёқиш ва фалокат сабаби тўхташ белгисини ўрнатиш',1),(@qid,'To\'xtash va hodisaga tegishli izlarni saqlash, ularning atrofini to\'sib, hodisa sodir bo\'lgan joyni aylanib o\'tishni tashkil etish uchun hamma mumkin bo\'lgan choralarni ko\'rish, IIOga xabar berish, tibbiy yordam berish','Остановиться и принять все возможные меры к сохранению следов происшествия, ограждению их и организации объезда места происшествия, сообщить о случившемся в милицию и принять меры для оказания доврачебной медицинской помощи пострадавшим','Тўхташ ва ҳодисага тегишли изларни сақлаш, уларнинг атрофини тўсиб, ҳодиса содир бўлган жойни айланиб ўтишни ташкил этиш учун ҳамма мумкин бўлган чораларни кўриш, ИИОга хабар бериш, тиббий ёрдам бериш',0);
