INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'To\'sqinlik tug\'dirishi mumkin bo\'lgan, o\'zidan keyin kelayotgan biron-bir haydovchi quvib o\'tishni boshlamagan bo\'lsa','Ни один из водителей, движущихся позади и которым он может создать помеху, не начал обгон',NULL,0),(@qid,'Shu bo\'lakda oldinda ketayotgan transport vositasining haydovchisi burilishga (chapga qayta tizilishga) ishora bermaganligiga','Водитель транспортного средства, движущегося впереди по той же полосе, не подал сигнал поворота (перестроения) налево',NULL,0),(@qid,'Quvib o\'tishni tugallaganda quvib o\'tilayotgan transport vositasiga to\'sqinlik tug\'dirmasdan, ilgarigi egallagan bo\'lagiga qayta olishiga','По завершении обгона он сможет, не создавая помех обгоняемому транспортному средству, вернуться на ранее занимаемую полосу',NULL,0),(@qid,'Barcha ko\'rsatilgan harakatlarni bajara olishida','Он может выполнить все указанные действия',NULL,1);
