INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yaqinni yorituvchi faralar yoki tumanga qarshi faralarni yoqishi kerak','Включить ближний свет фар или противотуманные фары','Яқинни ёритувчи фаралар ёки туманга қарши фараларни ёқиши керак',0),(@qid,'Yurgizgich kapotini ko\'tarib qo\'yishi kerak','Поднять капот двигателя','Юргизгич капотини кўтариб қўйиши керак',0),(@qid,'Falokat yorig\'lik ishoralari yoqishi,agar u yo\'q yoki nosoz bo\'lsa, falokat sababli to\'xtash belgisi aholi punktlarida transport vositasidan 15 metrdan, ulardan tashqarida esa 30 metrdan kam bo\'lmasligi masofasida o\'rnatishi kerak','Знаки аварийной остановки должны быть включены, а при их отсутствии или неисправностях должен быть установлен знак аварийной остановки на расстоянии не менее 15 метров от транспортного средства в населенных пунктах и не менее 30 метров вне их.','Фалокат ёриғлик ишоралари ёқиши,агар у йўқ ёки носоз бўлса, фалокат сабабли тўхташ белгиси аҳоли пунктларида транспорт воситасидан 15 метрдан, улардан ташқарида эса 30 метрдан кам бўлмаслиги масофасида ўрнатиши керак',1);
