INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Bolalar guruhini tashkiliy tashishda transport vositasida katta yoshli kuzatib boruvchi bo‘lishi shart','При организации группы детей в автомобиле должен присутствовать наблюдатель','Болалар гуруҳини ташкилий ташишда транспорт воситасида катта ёшли кузатиб борувчи бўлиши шарт',0),(@qid,'Bolalar guruhini tashkiliy tashish uchun mo‘ljallangan transport vositasining old va orqa tomoniga «Bolalar guruhini tashish» taniqlik belgisi o‘rnatilishi kerak','На передней и задней части транспортного средства; должна быть знак «Перевозка детей»','Болалар гуруҳини ташкилий ташиш учун мўлжалланган транспорт воситасининг олд ва орқа томонига «Болалар гуруҳини ташиш» таниқлик белгиси ўрнатилиши керак',0),(@qid,'Belgilangan yo‘nalishdagi transport vositalariga daxli bo‘lmagan avtobuslarda sakkiz va undan ortiq bolalarning tashkiliy tashilishi','Организованная перевозка восьми и более детей на автобусах, не вписывающихся в установленный маршрут','Белгиланган йўналишдаги транспорт воситаларига дахли бўлмаган автобусларда саккиз ва ундан ортиқ болаларнинг ташкилий ташилиши',0),(@qid,'Barcha sanab o\'tilgan talablar','Во всех перечисленных случаях','Барча санаб ўтилган талаблар',1);
