INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat yengil avtomobillarga ruxsat etiladi','Разрешается только легковым автомобилям','Фақат енгил автомобилларга рухсат этилади',0),(@qid,'Qattiq ulagichda ruxsat etiladi','Разрешается на жесткой сцепке','Қаттиқ улагичда рухсат этилади',0),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',1),(@qid,'Har qanday ulagichda ruxsat etiladi','Разрешается на любой сцепке','Ҳар қандай улагичда рухсат этилади',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Qanday hollarda aholi punktlaridan tashqarida yengil avtomobil haydovchisiga soatiga 90 km dan yuqori tezlikda harakatlanish taqiqlanadi?','В каких случаях водителю легкового автомобиля при езде вне населённых пунктов запрещается превышать установленную скорость?','Қандай ҳолларда аҳоли пунктларидан ташқарида енгил автомобиль ҳайдовчисига соатига 90 км дан юқори тезликда ҳаракатланиш тақиқланади?','Ҳаракатланиш тезлиги',NULL,NULL,NULL,NULL,'ptest',14,14);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat yo\'lda tezlik cheklangan belgilar o\'rnatilgan bo\'lsa','Только если на дороге установлены дорожные знаки; ограничивающие скорость движения','Фақат йўлда тезлик чекланган белгилар ўрнатилган бўлса',0),(@qid,'Faqat harakatlanayotgan tirkamali yengil avtomobillarga','Только если он двигается с прицепом','Фақат ҳаракатланаётган тиркамали енгил автомобилларга',0),(@qid,'Agar u boshqa transport vositasini shatakka olgan bo\'lsa','Если он буксирует другие транспортные средства','Агар у бошқа транспорт воситасини шатакка олган бўлса',0),(@qid,'Sanab o\'tilgan barcha hollarda','Во всех перечисленных случаях','Санаб ўтилган барча ҳолларда',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Egiluvchan yoki qattiq ulagichda shatakka olingan mexanik transport vositasida odamlar tashishga ruxsat etiladimi?','Разрешается ли перевозить людей при буксировке на гибкой или жесткой сцепке в буксируемом механическом транспортном средстве?','Эгилувчан ёки қаттиқ улагичда шатакка олинган механик транспорт воситасида одамлар ташишга рухсат этиладими?','Механик транспорт воситаларини шатакка олиш',NULL,NULL,NULL,NULL,'ptest',14,15);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Avtobus va trolleybusda ruxsat etiladi','Разрешается в автобусе и троллейбусе','Автобус ва троллейбусда рухсат этилади',0),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',0),(@qid,'Yuk va yengil avtomobillarda ruxsat etiladi','Разрешается в грузовом и легковом автомобилях','Юк ва енгил автомобилларда рухсат этилади',0),(@qid,'Yuk avtomobili kabinasida va yengil avtomobilda ruxsat etiladi','Разрешается в кабине грузового автомобиля и в легковом автомобиле','Юк автомобили кабинасида ва енгил автомобилда рухсат этилади',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Aholi yashaydigan joylardan tashqarida tirkamali yengil avtomobil haydovchisiga eng katta tezlikni soatiga necha kilometrdan oshirmasdan harakatlanishga ruxsat etiladi?','С какой максимальной скоростью разрешено движение водителю легкового автомобиля; буксирующего прицеп вне населенного пункта?','Аҳоли яшайдиган жойлардан ташқарида тиркамали енгил автомобил ҳайдовчисига энг катта тезликни соатига неча километрдан оширмасдан ҳаракатланишга рухсат этилади?','Ҳаракатланиш тезлиги',NULL,NULL,NULL,NULL,'ptest',14,16);
