INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositalari ixtiyoriga berilgan vakolatnomasi bo\'lgan shaxs o\'zining ishtirokida transport vositasini boshqa shaxsga boshqarishni topshirishi mumkinmi','Может ли лицо; имеющее доверенность на право распоряжения транспортным средством; передавать управление транспортным средством в своем присутствии другому лицу?','Транспорт воситалари ихтиёрига берилган ваколатномаси бўлган шахс ўзининг иштирокида транспорт воситасини бошқа шахсга бошқаришни топшириши мумкинми','Ҳайдовчиларнинг умумий вазифалари',NULL,NULL,NULL,NULL,'ptest',14,17);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Mumkin','Разрешена','Мумкин',0),(@qid,'Mumkin emas','Нельзя','Мумкин эмас',0),(@qid,'Bu shaxsda mazkur toifali transport vositasini boshqarishga haydovchilik guvohnomasi bo\'lgan taqdirda transport vositalari egalarining fuqarolik javobgarligini majburiy sug\'urta qilish bo\'yicha sug\'urta polisida ism-sharifi ko\'rsatilgan bo\'lsa yoki majburiy sug\'urta qilish bo\'yicha shartnoma ushbu transport vositasidan cheklanmagan shaxslarning foydalanishini hisobga olgan holda tuzilgan bo\'lsa','Может; при наличии у этого лица водительского удостоверения на право управления транспортным средством данной категории; и оно указано в страховом полисе обязательного страхования гражданской ответственности владельца транспортного средства','Бу шахсда мазкур тоифали транспорт воситасини бошқаришга ҳайдовчилик гувоҳномаси бўлган тақдирда транспорт воситалари эгаларининг фуқаролик жавобгарлигини мажбурий суғурта қилиш бўйича суғурта полисида исм-шарифи кўрсатилган бўлса ёки мажбурий суғурта қилиш бўйича шартнома ушбу транспорт воситасидан чекланмаган шахсларнинг фойдаланишини ҳисобга олган ҳолда тузилган бўлса',1);
