INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Taqiqlangan','Запрещена','Тақиқланган',0),(@qid,'Avtomagistral yaxshi ko\'rinadigan joylarda ruxsat etiladi','Разрешается в местах; где автомагистраль хорошо просматривается','Автомагистрал яхши кўринадиган жойларда рухсат этилади',0),(@qid,'Agar bir yo\'nalishda harakatlanish uchun uchta bo\'lak bo\'lsa, ruxsat etiladi','Разрешается, если имеются три полосы для движения в одном направлении','Агар бир йўналишда ҳаракатланиш учун учта бўлак бўлса, рухсат этилади',0),(@qid,'To\'xtab turish «To\'xtab turish joyi» yoki «Dam olish joyi» belgisi qo\'yilgan maxsus maydonchalarda ruxsat etiladi','Разрешается на специальных площадках для стоянки; обозначенных знаком «Место стоянки» или «Место отдыха»','Тўхтаб туриш «Тўхтаб туриш жойи» ёки «Дам олиш жойи» белгиси қўйилган махсус майдончаларда рухсат этилади',1);
