INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yakka 40 km/soat dan kam tezlik bilan harakat qiluvchi ikki g\'ildirakli mototsikllar, velosipedchilardan tashqari barcha transport vositalarini quvib o\'tishni taqiqlovchi hududga','Зону, в которой запрещается обгонять все транспортные средства, кроме одиночных, движущихся со скоростью менее 30 км/ч двухколесных мотоциклов, велосипедистов','Якка 40 км/соат дан кам тезлик билан ҳаракат қилувчи икки ғилдиракли мотоцикллар, велосипедчилардан ташқари барча транспорт воситаларини қувиб ўтишни тақиқловчи ҳудудга',0),(@qid,'Qatnov qismining torayishiga yoki qarama-qarshi yo\'nalishdan kelayotgan transport oqimini ajratuvchi 1,1 yoki 1,11 chizig\'iga yaqinlashayotganini','Приближение к сужению проезжей части или к линии разметки; разделяющей транспортные потоки противоположных направлений','Қатнов қисмининг торайишига ёки қарама-қарши йўналишдан келаётган транспорт оқимини ажратувчи 1,1 ёки 1,11 чизиғига яқинлашаётганини',1),(@qid,'Faqat belgilangan yo\'nalishdagi transport vositalari harakati uchun mo\'ljallangan qatnov qismi bo\'lagiga','Приближение к полосе проезжей части; предназначенной для движения только маршрутных транспортных средств','Фақат белгиланган йўналишдаги транспорт воситалари ҳаракати учун мўлжалланган қатнов қисми бўлагига',0);
