INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Hammasi','Все','Ҳаммаси',0),(@qid,'Hammasini, 40 km/soat dan kam tezlikda yakka harakat qilayotganlardan tashqari','Все, кроме одиночных, движущихся со скоростью менее 40 км/ч','Ҳаммасини, 40 км/соат дан кам тезликда якка ҳаракат қилаётганлардан ташқари',1),(@qid,'Yengil avtomobillar, mototsikllar va to\'la vazni 3,5 t dan kam bo\'lgan yuk avtomobillari. To\'la vazni 3,5 t dan ko\'p bulgan yuk avtomobillari','Легковые автомобили, мотоциклы и грузовые автомобили с полной массой менее 3,5 т','Енгил автомобиллар, мотоцикллар ва тўла вазни 3,5 т дан кам бўлган юк автомобиллари. Тўла вазни 3,5 т дан кўп булган юк автомобиллари',0),(@qid,'To\'la vazni 3,5 t dan ko\'p bo\'lgan yuk avtomobillari','Грузовые автомобили с полной массой более 3,5 т','Тўла вазни 3,5 т дан кўп бўлган юк автомобиллари',0);
