INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'To\'la vazni 3,5 t dan ortiq bo\'lgan yuk avtomobilining majburiy harakat yo\'nalishini','Обязательное направление движения грузовых автомобилей, полная масса которых более 3,5т','Тўла вазни 3,5 т дан ортиқ бўлган юк автомобилининг мажбурий ҳаракат йўналишини',0),(@qid,'Faqat yuk avtomobillari uchun harakat yo\'nalishini','Направление движения только для грузовых автомобилей','Фақат юк автомобиллари учун ҳаракат йўналишини',0),(@qid,'Yuk avtomobillari, traktorlar, o\'ziyurar mashinalar uchun, agar chorrahada ularning harakati yo\'nalishlardan biriga taqiqlangan bo\'lsa, tavsiya etiladigan harakat yo\'nalishini','Рекомендуемое направление движения для грузовых автомобилей, тракторов и самоходных машин, если на перекрестке их движение в одном из направлений запрещено','Юк автомобиллари, тракторлар, ўзиюрар машиналар учун, агар чорраҳада уларнинг ҳаракати йўналишлардан бирига тақиқланган бўлса, тавсия этиладиган ҳаракат йўналишини',1),(@qid,'Shaharlararo yuk tashuvchi yuk avtomillarining harakat yo\'nalishini','Направление движения грузовых автомобилей; осуществляющих междугородние перевозки','Шаҳарлараро юк ташувчи юк автомилларининг ҳаракат йўналишини',0);
