INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'70 km/soat dan ortmagan tezlik bilan ruxsat berilgan','Разрешена со скоростью не более 70 км/час','70 км/соат дан ортмаган тезлик билан рухсат берилган',0),(@qid,'Boshqarishni o\'rgatuvchi yo\'riqchi bilan bo\'lgan o\'rganuvchida etarli boshqarish malakasi bo\'lganda 60 km/soatdan ortiq bo\'lmagan tezlikka ruxsat etilgan','Разрешена со скоростью не более 60 км/час при достаточных навыках управления у обучаемого с мастером обучения вождению','Бошқаришни ўргатувчи йўриқчи билан бўлган ўрганувчида етарли бошқариш малакаси бўлганда 60 км/соатдан ортиқ бўлмаган тезликка рухсат этилган',0),(@qid,'Taqiqlangan','Запрещена','Тақиқланган',1),(@qid,'Agar o\'rganilayotgan mexanik transport vositasida taniqli belgilari qayd etilgan bo\'lsa, ruxsat etilgan','Разрешена, если механическое транспортное средство, на котором производится обучение, обозначено опознавательным знаком','Агар ўрганилаётган механик транспорт воситасида таниқли белгилари қайд этилган бўлса, рухсат этилган',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Siz reversiv harakatli yo\'lga burildingiz. Burilishdan keyin siz qaysi bo\'lak bo\'ylab harakatlanish huquqiga egasiz?','Вы поворачиваете на дорогу с реверсивным движением. По какой полосе после поворота Вы имеете право двигаться?','Сиз реверсив ҳаракатли йўлга бурилдингиз. Бурилишдан кейин сиз қайси бўлак бўйлаб ҳаракатланиш ҳуқуқига эгасиз?','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви',NULL,NULL,NULL,NULL,'ptest',17,1);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Aholi punktlarida istalgan bo\'lak bo\'ylab harakatlanishga ruxsat etiladi','В населенных пунктах движение разрешается по любой полосе','Аҳоли пунктларида исталган бўлак бўйлаб ҳаракатланишга рухсат этилади',0),(@qid,'Chetki o\'ng bo\'lak bo\'ylab. Faqat reversiv svetofor yoki boshqa bo\'laklar bo\'yicha ham harakatlanishga ruxsat etadigan \'\'bo\'laklar bo\'yicha harakatlanish yo\'nalishi\'\' belgisidan o\'tgandan so\'ng qayta tizilishga ruxsat etiladi','По крайней правой полосе. Перестраиваться разрешается только после проезда реверсивного светофора или знака “Направления движения по полосам”; разрешающего движение и по другим полосам','Четки ўнг бўлак бўйлаб. Фақат реверсив светофор ёки бошқа бўлаклар бўйича ҳам ҳаракатланишга рухсат этадиган \'\'бўлаклар бўйича ҳаракатланиш йўналиши\'\' белгисидан ўтгандан сўнг қайта тизилишга рухсат этилади',1),(@qid,'Aholi punktlaridan tashqarida qatnov qismining iloji boricha o\'ng chetiga yaqinroqda','Вне населенных пунктов по возможности ближе к правому краю проезжей части','Аҳоли пунктларидан ташқарида қатнов қисмининг иложи борича ўнг четига яқинроқда',0);
