INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Transport vositasi majburiy to\'xtaganda','При вынужденной остановке транспортного средства','Транспорт воситаси мажбурий тўхтаганда',0),(@qid,'Haydovchining xohishiga ko\'ra shu shart bilanki, bu xavf-xatardan holi bo\'lsa va boshqa harakat qatnashchilariga halaqit bermasa','По усмотрению водителя при условии, что это будет безопасно и не создает помех другим участникам движения','Ҳайдовчининг хоҳишига кўра шу шарт биланки, бу хавф-хатардан ҳоли бўлса ва бошқа ҳаракат қатнашчиларига ҳалақит бермаса',0),(@qid,'Trotuar tomondan yoki yo\'l yoqasidan iloji bo\'lmasa shu shart bilanki bu hol xavf-xatarsiz bo\'lsa va boshqa harakat qatnashchilariga halaqit bermasa','Если это невозможно сделать со стороны тротуара или обочины и при условии, что это будет безопасно и создает помех другим участникам движения','Тротуар томондан ёки йўл ёқасидан иложи бўлмаса шу шарт биланки бу ҳол хавф-хатарсиз бўлса ва бошқа ҳаракат қатнашчиларига ҳалақит бермаса',1);
