INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositalariga sidirg\'a oq chiziq bilan ajratilgan va «Belgilangan yo\'nalishdagi transport vositalari uchun mo\'ljallangan bo\'lak» yo\'l belgisi bilan belgilangan yo\'lning o\'ng bo\'lagida to\'xtab turishga ruxsat etiladimi?','Разрешается ли стоянка транспортных средств на правой полосе дороги отделенной сплошной белой линией разметки и обозначенной дорожным знаком «Полоса для маршрутных транспортных средств»?','Транспорт воситаларига сидирға оқ чизиқ билан ажратилган ва «Белгиланган йўналишдаги транспорт воситалари учун мўлжалланган бўлак» йўл белгиси билан белгиланган йўлнинг ўнг бўлагида тўхтаб туришга рухсат этиладими?','Ётиқ чизиқлар',NULL,NULL,NULL,NULL,'ptest',19,14);
