INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Piyodalarga mazkur yo\'nalishning qatnov qismidan butunlay o\'tib olishlariga imkon berishi','Дать возможность пешеходам закончить переход проезжей части данного направления','Пиёдаларга мазкур йўналишнинг қатнов қисмидан бутунлай ўтиб олишларига имкон бериши',1),(@qid,'Yo\'l-transport falokati oldini olish uchun tovush ishora berishi va asosiy yo\'lda bo\'lgani sababli piyodalarga yo\'l bermay o\'tish joyidan o\'tishi','Подать звуковой сигнал для предотвращения дорожно-транспортного происшествия и не уступая дорогу пешеходам проехать переход так как он находится на главной дороге','Йўл-транспорт фалокати олдини олиш учун товуш ишора бериши ва асосий йўлда бўлгани сабабли пиёдаларга йўл бермай ўтиш жойидан ўтиши',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositasi ushbu taniqlik belgisi bilan belgilanadi:','Таким опознавательным знаком обозначается транспортное средство:','Транспорт воситаси ушбу таниқлик белгиси билан белгиланади:','Мансабдор шахсларнинг ва фуқароларнинг йўл ҳаракати хавфсизлигини таъминлаш, транспорт воситаларини йўлга чиқариш, рақам ва таниқли белгиларини ўрнатиш бўйича мажбуриятлари','pt_d6da657757d99a01.webp',NULL,NULL,NULL,'ptest',20,10);
