INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Jarohatdan behushlanganda birinchi tibbiy yordamni qanday ko\'rsatish kerak?','Как оказать первую медицинскую помощь при травматическом шоке?','Жароҳатдан беҳушланганда биринчи тиббий ёрдамни қандай кўрсатиш керак?','Биринчи тиббий ёрдам',NULL,NULL,NULL,NULL,'ptest',21,9);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Kiyim-boshni echish yoki bo\'shatish, toza havo kelishini taminlash. Nashatir spirti hidlatish. Yuzga sovuq suv sepish. Peshonaga va gardanga iliq malhamlar qo\'yish','Одежду снять или ослабить. Обеспечить приток свежего воздуха. Дать понюхать нашатырный спирт. Обрызгать лицо холодной водой. На лоб и затылок наложить теплые примочки','Кийим-бошни ечиш ёки бўшатиш, тоза ҳаво келишини таъминлаш. Нашатир спирти ҳидлатиш. Юзга совуқ сув сепиш. Пешонага ва гарданга илиқ малҳамлар қўйиш',0),(@qid,'Mutloq tinch qo\'yish. Boshni tushirish, oyoqlarni ko\'tarish, badanni isitish. Qaynoq ichimlik (choy va shu kabilar) berish. Bog\'langan jgutni shifokorsiz echmaslik va bo\'shatmaslik','Полный покой. Голову опустить, ноги приподнять, тело согреть. Дать выпить горячее питье (чай и т.д.). Наложенный жгут без врача не снимать и не ослаблять','Мутлоқ тинч қўйиш. Бошни тушириш, оёқларни кўтариш, баданни иситиш. Қайноқ ичимлик (чой ва шу кабилар) бериш. Боғланган жгутни шифокорсиз ечмаслик ва бўшатмаслик',1);
