INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar yo\'l bo\'lagi sidirg\'a chiziq bilan ajratilib, belgi bilan belgilangan bo\'lsa, avtobus haydovchisining bo\'lak bo\'ylab harakatlanishiga ruxsat etiladimi?','Разрешается ли водителю автобуса двигаться по полосе, обозначенной этим знаком, если полоса отделена сплошной линией разметки?','Агар йўл бўлаги сидирға чизиқ билан ажратилиб, белги билан белгиланган бўлса, автобус ҳайдовчисининг бўлак бўйлаб ҳаракатланишига рухсат этиладими?','Йўналишли транспорт воситаларининг имтиёзлари','pt_98cce17ba0bee7e6.webp',NULL,NULL,NULL,'ptest',21,20);
