INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Oldindan yaqin fara chiroqlarini yoqib va uzluksiz tovush ishorasini berib, eng kam tezlik bilan turgan transport vositasini aylanib o\'tishi','Объехать стоящее транспортное средство на минимальной скорости, заблаговременно включив ближний свет фар и периодически подавая звуковой сигнал','Олдиндан яқин фара чироқларини ёқиб ва узлуксиз товуш ишорасини бериб, энг кам тезлик билан турган транспорт воситасини айланиб ўтиши',0),(@qid,'Qatnov qismidan o\'tayotgan bolalarga yo\'l berishi','Уступить дорогу детям переходящим проезжую часть','Қатнов қисмидан ўтаётган болаларга йўл бериши',1),(@qid,'Bu yo\'l qismidan o\'tishi kerak, chunki bolalar qatnov qismini piyodalar o\'tish joyidan kesib o\'tmayaptilar','Проехать данный участок, так как дети пересекают проезжую часть не по пешеходному переходу','Бу йўл қисмидан ўтиши керак, чунки болалар қатнов қисмини пиёдалар ўтиш жойидан кесиб ўтмаяптилар',0);
