INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat agar uning orqasida boshqa transport vositasi harakatlanayotgan holda','Только в случае если за ним движется другое транспортное средство','Фақат агар унинг орқасида бошқа транспорт воситаси ҳаракатланаётган ҳолда',0),(@qid,'Faqat agar uning transport vositasi burilishini ko\'rsatuvchi chiroqlar bilan jihozlangan holda','Только в случае если его транспортное средство имеет указатели поворотов','Фақат агар унинг транспорт воситаси бурилишини кўрсатувчи чироқлар билан жиҳозланган ҳолда',0),(@qid,'Faqat serqatnov harakatli yo\'lda','Только на дороге с интенсивным движением','Фақат серқатнов ҳаракатли йўлда',0),(@qid,'Faqat u harakatning boshqa ishtirokchilarini chalg\'itmagan hollarda','Сигнал не подается в случаях когда он может ввести в заблуждение других участников движения','Фақат у ҳаракатнинг бошқа иштирокчиларини чалғитмаган ҳолларда',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Siz quvib o\'tish uchun chiqdingiz va bexosdan ro\'paradan kelayotgan avtobusni ko\'rib qoldingiz. Agar Siz quvib o\'tishni tugallay olishingizga ishonchingiz bo\'lmasa, Siz:','Вы выехали для обгона и неожиданно увидели встречный автомобиль. Если Вы не уверены в том что сумеете завершить обгон. Вы должны:','Сиз қувиб ўтиш учун чиқдингиз ва бехосдан рўпарадан келаётган автобусни кўриб қолдингиз. Агар Сиз қувиб ўтишни тугаллай олишингизга ишончингиз бўлмаса, Сиз:','Қувиб ўтиш',NULL,NULL,NULL,NULL,'ptest',22,9);
