INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositalari chorrahani quyidagi tartibda kesib o\'tadilar:','Транспортные средства проедут перекресток в следующем порядке:','Транспорт воситалари чорраҳани қуйидаги тартибда кесиб ўтадилар:','Тартибга солинган чорраҳалар','pt_df1650f2fefe0a59.webp',NULL,NULL,NULL,'ptest',23,5);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qizil avtomobil, tramvay ayni vaqtda yashil avtomobil bilan','Красный автомобиль, трамвай одновременно с зеленым автомобилем','Қизил автомобил, трамвай айни вақтда яшил автомобил билан',1),(@qid,'Tramvay, qizil, yashil avtomobillar','Трамвай, красный, зеленый автомобили','Трамвай, қизил, яшил автомобиллар',0),(@qid,'Tramvay, ayni vaqtda yashil avtomobil, qizil avtomobil','Трамвай одновременно с зеленым автомобилем, красный автомобиль','Трамвай, айни вақтда яшил автомобил, қизил автомобил',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Bu yotiq chiziq nimani bildiradi?','Что означает эта разметка?','Бу ётиқ чизиқ нимани билдиради?','Ётиқ чизиқлар','pt_2f629b39aaf846ae.webp',NULL,NULL,NULL,'ptest',23,6);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat avtobusning harakatlanishi uchun mo\'ljallangan bo\'lakni bildiradi','Обозначает полосу предназначенную только для движения автобусов','Фақат автобуснинг ҳаракатланиши учун мўлжалланган бўлакни билдиради',0),(@qid,'Faqat belgilangan yo\'nalishdagi transport vositalarining harakatlanishi uchun mo\'ljallangan bo\'lakni bildiradi','Обозначает полосу предназначенную только для движения маршрутных транспортных средств','Фақат белгиланган йўналишдаги транспорт воситаларининг ҳаракатланиши учун мўлжалланган бўлакни билдиради',1),(@qid,'Avtobuslar va trolleybuslarning harakatlanishi uchun mo\'ljallangan bo\'lakni bildiradi','Обозначает полосу предназначенную для движения автобусов и троллейбусов','Автобуслар ва троллейбусларнинг ҳаракатланиши учун мўлжалланган бўлакни билдиради',0),(@qid,'Avtobuslar va marshrutli taksi (alohida kichik avtobuslar)ning harakatlanishi uchun mo\'ljallangan bo\'lakni bildiradi','Обозначает полосу предназначенную для движения автобусов и маршрутных такси (особо малых автобусов)','Автобуслар ва маршрутли такси (алоҳида кичик автобуслар)нинг ҳаракатланиши учун мўлжалланган бўлакни билдиради',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Mototsiklning haydovchisi qanday holda chapga to\'g\'ri burildi?','В каком случае водитель мотоцикла повернул налево правильно?','Мотоциклнинг ҳайдовчиси қандай ҳолда чапга тўғри бурилди?','тартибга солувчининг ишоралари','pt_a3b6ad92bbe9067c.webp',NULL,NULL,NULL,'ptest',23,7);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Chorrahaga chiqdi, yuk avtomobilini o\'tkazib yubordi, burilishni tugalladi','Выехал на перекресток, пропустил грузовой автомобиль, закончил поворот','Чорраҳага чиқди, юк автомобилини ўтказиб юборди, бурилишни тугаллади',0),(@qid,'Chorrahaga chiqdi va tartibga soluvchining ruxsat etuvchi ishorasini kutib, burilishni tugalladi','Выехал на перекресток и, дождавшись разрешающего жеста регулировщика, закончил поворот','Чорраҳага чиқди ва тартибга солувчининг рухсат этувчи ишорасини кутиб, бурилишни тугаллади',0),(@qid,'To\'xtadi va tartibga soluvchining ruxsat etuvchi ishorasida to\'xtamay chapga burildi','Остановится и при разрешающем жесте регулировщика повернёт налево','Тўхтади ва тартибга солувчининг рухсат этувчи ишорасида тўхтамай чапга бурилди',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Burilish vaqtida qatnov qismining kesishmasidan chiqishda transport vositasi qayerda bo\'lmasligi kerak?','Где не должно оказаться транспортное средство при выезде с пересечения проезжих частей во время поворота?','Бурилиш вақтида қатнов қисмининг кесишмасидан чиқишда транспорт воситаси қаерда бўлмаслиги керак?','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви',NULL,NULL,NULL,NULL,'ptest',23,8);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Chap bo\'lakda, agar o\'ng bo\'lak bo\'sh bo\'lsa','На левой полосе, если свободна правая полоса','Чап бўлакда, агар ўнг бўлак бўш бўлса',0),(@qid,'Qarama-qarshi harakat tomonida','На стороне встречного движения','Қарама-қарши ҳаракат томонида',1),(@qid,'Agar bir yo\'nalishda harakatlanish uchun uchtadan kam bo\'lmagan bo\'lak bo\'lganda, chap bo\'lakda','На левой полосе, если имеются не менее трех полос для движения в одном направлении','Агар бир йўналишда ҳаракатланиш учун учтадан кам бўлмаган бўлак бўлганда, чап бўлакда',0),(@qid,'Ruxsat etilgan to\'la vazni 3,5 t. dan ortiq bo\'lgan faqat yuk avtomobillariga bir yo\'nalishdan harakatlanishi uchun ikkita bo\'lak bo\'lsa, chap bo\'lakda','На левой полосе, если имеется две полосы для движения в одном направлении только грузовым автомобилям с разрешенной максимальной массой более 3.5 т','Рухсат этилган тўла вазни 3,5 т. дан ортиқ бўлган фақат юк автомобилларига бир йўналишдан ҳаракатланиши учун иккита бўлак бўлса, чап бўлакда',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar transport vositasining ishchi tormozining samaradorligi Qoidalar talabiga javob bermasa, u holda siz majbursiz:','Если эффективность торможения рабочей тормозной системы транспортных средств не отвечает требованиям Правил, то Вы должны:','Агар транспорт воситасининг ишчи тормозининг самарадорлиги Қоидалар талабига жавоб бермаса, у ҳолда сиз мажбурсиз:','Транспорт воситаларидан фойдаланишни тақиқловчи шартлар',NULL,NULL,NULL,NULL,'ptest',23,9);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Belgilangan safarni davom ettirishga, bunda kunning yorug\' vaqtida yaqinni yorituvchi fara chirog\'ini yoqishga','Продолжить намеченную поездку, при этом в светлое время суток включить ближний свет фар','Белгиланган сафарни давом эттиришга, бунда куннинг ёруғ вақтида яқинни ёритувчи фара чироғини ёқишга',0),(@qid,'Bundan keyingi harakatni to\'xtatishga','Прекратить дальнейшее движение','Бундан кейинги ҳаракатни тўхтатишга',0),(@qid,'Nosozlikni o\'sha joyda bartaraf etishga, agar buning iloji bo\'lmasa zarur ehtiyot choralariga rioya qilgan holda to\'xtab turish yoki tamirlashga olib borishga','Устранить неисправность на месте, а если это невозможно. следовать к месту стоянки или ремонта с соблюдением необходимых мер предосторожности','Носозликни ўша жойда бартараф этишга, агар бунинг иложи бўлмаса зарур эҳтиёт чораларига риоя қилган ҳолда тўхтаб туриш ёки таъмирлашга олиб боришга',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Ko\'k avtomobilga qaysi yo\'nalishda harakatlanishga ruxsat etiladi?','В каком направлении разрешается движение синему автомобилю?','Кўк автомобилга қайси йўналишда ҳаракатланишга рухсат этилади?','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви','pt_bc985afb658e1f7b.webp',NULL,NULL,NULL,'ptest',23,10);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat orqa yo\'nalishda','Только в обратном направлении','Фақат орқа йўналишда',0),(@qid,'To\'g\'riga, chap va orqa yo\'nalishda','Прямо, налево и в обратном направлении','Тўғрига, чап ва орқа йўналишда',0),(@qid,'Chap va orqa yo\'nalishda','Налево и в обратном направлении','Чап ва орқа йўналишда',1),(@qid,'Barcha yo\'nalishlarda','Во всех направлениях','Барча йўналишларда',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Avtomagistralda ajratuvchi bo\'lakning uzilishlariga kirishga ruxsat etiladimi?','Разрешается ли въезд в разрывы разделительной полосы на автомагистрали?','Автомагистралда ажратувчи бўлакнинг узилишларига киришга рухсат этиладими?','Автомагистралларда ҳаракатланиш',NULL,NULL,NULL,NULL,'ptest',23,11);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat etiladi','Разрешается','Рухсат этилади',0),(@qid,'Faqat orqa burilish uchun ruxsat etiladi, to\'la vazni 3,5 t dan ortiq bo\'lgan yuk avtomobillarning haydovchilari bundan mustasno','Разрешается только для разворота, кроме водителей грузовых автомобилей полной массой более 3,5 т','Фақат орқа бурилиш учун рухсат этилади, тўла вазни 3,5 т дан ортиқ бўлган юк автомобилларнинг ҳайдовчилари бундан мустасно',0),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',1),(@qid,'Belgilangan yo\'nalishdagi transport vositalariga ruxsat etiladi','Разрешается маршрутным транспортным средствам','Белгиланган йўналишдаги транспорт воситаларига рухсат этилади',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Chorrahani ikkinchi bo\'lib kim kesib o\'tadi?','Вторым проедет перекресток:','Чорраҳани иккинчи бўлиб ким кесиб ўтади?','Тартибга солинмаган чорраҳалар асосий йўл йўналиши ўзгариши','pt_4150dcf45c3a6935.webp',NULL,NULL,NULL,'ptest',23,12);
