INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Haydovchi yo\'l-transport hodisasida shikastlangan transport vositasini shatakka olish uchun yuk avtomobilini ichki ishlar organi xodimi ixtiyoriga qanday holda berishi kerak?','В каком случае водитель должен предоставить грузовой автомобиль работнику органов внутренних дел для буксировки транспортного средства поврежденного при дорожно транспортном происшествии?','Ҳайдовчи йўл-транспорт ҳодисасида шикастланган транспорт воситасини шатакка олиш учун юк автомобилини ички ишлар органи ходими ихтиёрига қандай ҳолда бериши керак?','Ҳайдовчиларнинг умумий вазифалари',NULL,NULL,NULL,NULL,'ptest',23,13);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat shu holdaki, agar shatakka olish yo\'l-yo\'lakay yo\'nalishda amalga oshirilsa','Только в случае, если буксировка будет осуществляться в попутном направлении','Фақат шу ҳолдаки, агар шатакка олиш йўл-йўлакай йўналишда амалга оширилса',0),(@qid,'Har qanday holda, fuqarolarga tegishli transport vositalaridan tashqari','В любом случае, кроме транспортных средств принадлежащих гражданам','Ҳар қандай ҳолда, фуқароларга тегишли транспорт воситаларидан ташқари',1),(@qid,'Haydovchining istagi bo\'yicha','По усмотрению водителя','Ҳайдовчининг истаги бўйича',0);
