INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Sirpanchiq yo\'lda yurgizgich bilan tormozlashni qo\'llash orqa uzatmali avtomobil uchun:','Применение торможения двигателем на скользкой дороге для заднеприводного автомобиля:','Сирпанчиқ йўлда юргизгич билан тормозлашни қўллаш орқа узатмали автомобил учун:','Ҳаракат хафсизлиги асослари',NULL,NULL,NULL,NULL,'ptest',24,3);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Avtomobilning turg\'unligini oshiradi','Повышает устойчивость автомобиля','Автомобилнинг турғунлигини оширади',1),(@qid,'Avtomobilning turg\'unligini kamaytiradi','Снижает устойчивость автомобиля','Автомобилнинг турғунлигини камайтиради',0),(@qid,'Avtomobilning turg\'unligiga hech qanday tasir ko\'rsatmaydi','Не оказывает какого-либо влияния на устойчивость автомобиля','Автомобилнинг турғунлигига ҳеч қандай таъсир кўрсатмайди',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Aholi punktlarida relssiz transport vositalariga, agar bir yo\'nalishda uchta va undan ortiq harakatlanish bo\'lagi bo\'lganda, qaysi bo\'lakdan harakatlanishga ruxsat etiladi? Yuk avtomobillari hisobga kirmaydi','По какой полосе разрешается движение безрельсовых транспортных средств в населенных пунктах, если имеются три полосы и более в одном направлении? Грузовые автомобили не учитывать','Аҳоли пунктларида рельссиз транспорт воситаларига, агар бир йўналишда учта ва ундан ортиқ ҳаракатланиш бўлаги бўлганда, қайси бўлакдан ҳаракатланишга рухсат этилади? Юк автомобиллари ҳисобга кирмайди','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви',NULL,NULL,NULL,NULL,'ptest',24,4);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Har qanday bo\'lak bo\'yicha','По любой полосе','Ҳар қандай бўлак бўйича',0),(@qid,'Iloji boricha qatnov qismining o\'ng chekkasiga yaqin bo\'lak bo\'yicha','По возможности ближе к правому краю проезжей части','Иложи борича қатнов қисмининг ўнг чеккасига яқин бўлак бўйича',0),(@qid,'Chapki chekkadan tashqari har qanday bo\'lak bo\'yicha. Unga faqat boshqa bo\'laklarda harakat serqatnov bo\'lganda, shuningdek, chapga burilish, orqaga qayrilish va bir tomonlama harakat tashkil qilingan yo\'lda to\'xtash uchun o\'tishga ruxsat etiladi','По любой полосе кроме крайней левой, на которою разрешается выезжать только при интенсивном движении на других полосах а также для поворота налево,разворота и остановки на дороге с односторонним движением','Чапки чеккадан ташқари ҳар қандай бўлак бўйича. Унга фақат бошқа бўлакларда ҳаракат серқатнов бўлганда, шунингдек, чапга бурилиш, орқага қайрилиш ва бир томонлама ҳаракат ташкил қилинган йўлда тўхташ учун ўтишга рухсат этилади',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Harakatni boshlashdan avval shaharlararo avtobus haydovchilari nima qilishlari kerak?','Что должны сделать водители междугородних автобусов, прежде чем начать движения?','Ҳаракатни бошлашдан аввал шаҳарлараро автобус ҳайдовчилари нима қилишлари керак?','Одам ташиш',NULL,NULL,NULL,NULL,'ptest',24,5);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'lovchilarga halokat bo\'lganda chiqish joylaridan foydalanish haqida tushuntirish','Объяснить пассажирам об использовании аварийные выходы','Йўловчиларга ҳалокат бўлганда чиқиш жойларидан фойдаланиш ҳақида тушунтириш',1),(@qid,'Yo\'lovchilarga chiqish, undan tushish va unga joylashish tartibi haqida tushuntirish','Объяснить пассажирам, как выйти, сойти и сесть на автобус','Йўловчиларга чиқиш, ундан тушиш ва унга жойлашиш тартиби ҳақида тушунтириш',0),(@qid,'Yo\'lovchilarga harakatlanish vaqtida salon ichida yurish mumkin emasligi haqida tushuntirish','Объяснить пассажирам; что во время движения нельзя ходить в салоне автобуса','Йўловчиларга ҳаракатланиш вақтида салон ичида юриш мумкин эмаслиги ҳақида тушунтириш',0);
