INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'lning xavfli joylaridagi harakatlanish bo\'lagi chegarasini bildiradi','Обозначает границы полос движения в опасных местах на дорогах','Йўлнинг хавфли жойларидаги ҳаракатланиш бўлаги чегарасини билдиради',0),(@qid,'Yo\'lning boshqa qismlarida yo\'l chetidagi to\'siqlarning yon chegarasini belgilaydi','Обозначает боковые поверхности ограждений дорог на других участках','Йўлнинг бошқа қисмларида йўл четидаги тўсиқларнинг ён чегарасини белгилайди',1),(@qid,'Xavfli yo\'l qismlarida bordyurlarni belgilaydi','Обозначает бордюры на опасных участках','Хавфли йўл қисмларида бордюрларни белгилайди',0),(@qid,'Yo\'naltiruvchi ustunchalar, beton yoki temir-beton ustunchalar, to\'siq ustunchalari va shunga o\'xshashlarni belgilaydi','Обозначает направляющие столбики, надолбы, опоры ограждений и т.п','Йўналтирувчи устунчалар, бетон ёки темир-бетон устунчалар, тўсиқ устунчалари ва шунга ўхшашларни белгилайди',0);
