INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat etiladi','Разрешается','Рухсат этилади',0),(@qid,'Taqiqlanadi','Запрещается','Тақиқланади',1),(@qid,'Ruxsat etiladi, agar qizil avtomobil 40 km/soatdan kam tezlik bilan harakatlanayotgan bo\'lsa','Разрешается, если красный автомобиль движется со скоростью менее 40 км/час','Рухсат этилади, агар қизил автомобил 40 км/соатдан кам тезлик билан ҳаракатланаётган бўлса',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Avtomobilga o\'rnatilgan bu taniqlik belgi nimani bildiradi?','Что означает данный опознавательный знак установленный на автомобиле?','Автомобилга ўрнатилган бу таниқлик белги нимани билдиради?','Мансабдор шахсларнинг ва фуқароларнинг йўл ҳаракати хавфсизлигини таъминлаш, транспорт воситаларини йўлга чиқариш, рақам ва таниқли белгиларини ўрнатиш бўйича мажбуриятлари','pt_900cd74be128717c.webp',NULL,NULL,NULL,'ptest',24,14);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Avtomobil shifokor haydovchiga tegishli ekanini','Автомобиль принадлежит водителю врачу','Автомобил шифокор ҳайдовчига тегишли эканини',1),(@qid,'Avtomobil haydovchi nogironga tegishli ekanini','Автомобиль принадлежит водителю инвалиду','Автомобил ҳайдовчи ногиронга тегишли эканини',0),(@qid,'Avtomobil uyda tibbiy yordami ko\'rsatish uchun mo\'ljallanganini','Автомобиль предназначен для оказания медпомощи на дому','Автомобил уйда тиббий ёрдами кўрсатиш учун мўлжалланганини',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar qatnov qismining kengligi chetki chap bo\'lakdan qayrilish uchun yetarli bo\'lmasa, qoidalar qayrilishni qatnov qismining o\'ng chekkasi yoki yo\'lning o\'ng yoqasidan amalga oshirishga yo\'l qo\'yadimi?','Если ширина проезжей части недостаточна для разворота из крайнего левого положения; допускается ли производить его от правого края проезжей части или с правой обочины?','Агар қатнов қисмининг кенглиги четки чап бўлакдан қайрилиш учун етарли бўлмаса, қоидалар қайрилишни қатнов қисмининг ўнг чеккаси ёки йўлнинг ўнг ёқасидан амалга оширишга йўл қўядими?','Ҳаракатланишни бошлаш, манёвр қилиш',NULL,NULL,NULL,NULL,'ptest',24,15);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qatnov qismining faqat o\'ng chekkasidan yo\'l qo\'yadi. Yo\'lning o\'ng yoqasidan yo\'l qo\'yilmaydi','Допускается только от правого края проезжей части. С правой обочины не допускается','Қатнов қисмининг фақат ўнг чеккасидан йўл қўяди. Йўлнинг ўнг ёқасидан йўл қўйилмайди',0),(@qid,'Yo\'l qo\'yiladi. Bunda qayrilayotgan haydovchi yo\'lakay va qarama-qarshi kelayotgan transport vositalarini o\'tkazib yuborishi kerak','Допускается при этом водитель производящий разворот, должен уступить дорогу попутным и встречным транспортным средствам','Йўл қўйилади. Бунда қайрилаётган ҳайдовчи йўлакай ва қарама-қарши келаётган транспорт воситаларини ўтказиб юбориши керак',1),(@qid,'Yo\'l qo\'yilmaydi','Не допускается','Йўл қўйилмайди',0);
