INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Bir marta ko\'krak qafasi bosiladi, bir marta havo puflanadi va hokazo','Один раз надавливать на грудную клетку, один раз вдувать воздух и т.д','Бир марта кўкрак қафаси босилади, бир марта ҳаво пуфланади ва ҳоказо',0),(@qid,'Ikki marta havo puflanadi, so\'ng yurak sohasi 30 marta bosiladi va hokazo','Два раза вдувать воздух, затем 30 раз надавливать на область сердца и т.д','Икки марта ҳаво пуфланади, сўнг юрак соҳаси 30 марта босилади ва ҳоказо',1),(@qid,'2-3 marta havo puflangandan so\'ng 15 marta ko\'krak qafasi bosiladi','После 2-3 раз вдуваний воздуха 15 раз надавливать на грудную клетку','2-3 марта ҳаво пуфлангандан сўнг 15 марта кўкрак қафаси босилади',0);
