INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Xavfsizlik choralariga rioya qilgan holda tezlikni kamaytirishi va xavfli yo\'l qismidan o\'tishi','Снизить скорость и проехать опасный участок соблюдая меры безопасности','Хавфсизлик чораларига риоя қилган ҳолда тезликни камайтириши ва хавфли йўл қисмидан ўтиши',0),(@qid,'Tezlikni transport vositasi to\'xtagunicha kamaytirishi yoki to\'siqni aylanib o\'tishning boshqa harakat qatnashchilari uchun xavfsiz choralarni ko\'rishi','Снизить скорость вплоть до остановки транспортного средства и принять меры к безопасному для других участников движения объезду препятствия','Тезликни транспорт воситаси тўхтагунича камайтириши ёки тўсиқни айланиб ўтишнинг бошқа ҳаракат қатнашчилари учун хавфсиз чораларни кўриши',1),(@qid,'Sodir bo\'lgan hodisa haqida ichki ishlar organlariga xabar berishi','Сообщить о случившемся в органы внутренних дел','Содир бўлган ҳодиса ҳақида ички ишлар органларига хабар бериши',0),(@qid,'DYHX xizmatining eng yaqin mahkamasiga yoki IIO idorasiga kelishi va paydo bo\'lgan to\'sqinliklar yoki xavf-xatar to\'g\'risida xabar berishi','Прибыть на ближайший пост ГСБДД или в орган милиции и сообщить о возникшем препятствии или опасности','ДЙҲХ хизматининг энг яқин маҳкамасига ёки ИИО идорасига келиши ва пайдо бўлган тўсқинликлар ёки хавф-хатар тўғрисида хабар бериши',0);
