INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Sariq avtomobilga u orqadan kelayotgani uchun yo\'l bermay, mo\'ljallangan yo\'nalishda chorrahani kesib o\'tishi','Проехать перекресток в намеченном направлении, не уступая дорогу желтому автомобилю, так как тот движется сзади','Сариқ автомобилга у орқадан келаётгани учун йўл бермай, мўлжалланган йўналишда чорраҳани кесиб ўтиши',0),(@qid,'Qarama-qarshi harakat bo\'lagiga darhol qayta tizilishi','Немедленно перестроиться на полосу встречного движения','Қарама-қарши ҳаракат бўлагига дарҳол қайта тизилиши',0),(@qid,'Tezlikni kamaytirishi, sariq avtomobilga quvib o\'tishni tugallashiga imkon berishi, so\'ng esa chapga burilishni ko\'rsatadigan chiroqni yoqib, chapga burilishi lozim','Снизить скорость - дать возможность желтому автомобилю завершив обгон, а затем повернуть налево','Тезликни камайтириши, сариқ автомобилга қувиб ўтишни тугаллашига имкон бериши, сўнг эса чапга бурилишни кўрсатадиган чироқни ёқиб, чапга бурилиши лозим',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Bunday yo\'l belgisi bilan belgilangan yo\'l qismlarida ruxsat etilgan to\'la vazni 3,5 t dan ortiq bo\'lgan yuk avtomobillarining qanday yuqori tezlik bilan harakatlanishiga ruxsat etiladi?','С какой максимальной скоростью разрешается движение грузовых автомобилей с разрешенной максимальной массой более 3,5 т на участках дорог обозначенных таким дорожным знаком?','Бундай йўл белгиси билан белгиланган йўл қисмларида рухсат этилган тўла вазни 3,5 т дан ортиқ бўлган юк автомобилларининг қандай юқори тезлик билан ҳаракатланишига рухсат этилади?','Ҳаракатланиш тезлиги','pt_2a1f0e13c73a2b3b.webp',NULL,NULL,NULL,'ptest',26,4);
