INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Boshqarishni o\'rgatish huquqini beruvchi hujjatlari bo\'lgan haydashni o\'rgatuvchi instruktor','Мастер обучения вождению имеющий документы на право обучения вождению','Бошқаришни ўргатиш ҳуқуқини берувчи ҳужжатлари бўлган ҳайдашни ўргатувчи инструктор',1),(@qid,'Tajribali haydovchi','Опытный водител','Тажрибали ҳайдовчи',0),(@qid,'3 yillik ishlagan davri bo\'lgan haydovchi','Водитель со стажем 3 года','3 йиллик ишлаган даври бўлган ҳайдовчи',0),(@qid,'5 yil haydovchilik ishlagan davriga ega bo\'lgan 1 - va 2 - toifa haydovchilar','Водитель 1 -го и 2-го класса; имеющий водительский стаж 5 лет','5 йил ҳайдовчилик ишлаган даврига эга бўлган 1 - ва 2 - тоифа ҳайдовчилар',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositalari chorrahani quyidagi tartibda kesib o\'tadi:','Транспортные средства проедут перекресток следующем порядке:','Транспорт воситалари чорраҳани қуйидаги тартибда кесиб ўтади:','Тартибга солинмаган чорраҳалар асосий йўл йўналиши ўзгариши','pt_41f6410f92c862df.webp',NULL,NULL,NULL,'ptest',26,6);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'1- va 2-tramvaylar ayni vaqtda yashil avtomobil bilan, qizil, ko\'k avtomobillar','Трамваи 1 и 2 одновременно с зеленым автомобилем, красный, синий автомобили','1- ва 2-трамвайлар айни вақтда яшил автомобил билан, қизил, кўк автомобиллар',0),(@qid,'1-tramvay ayni vaqtda yashil avtomobil bilan, qizil avtomobil; 2-tramvay va ko\'k avtomobil bir vaqtda','Трамвай 1 одновременно с зеленым автомобилем, красный автомобиль, трамвай 2, синий автомобиль','1-трамвай айни вақтда яшил автомобил билан, қизил автомобил; 2-трамвай ва кўк автомобил бир вақтда',1);
