INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Avtobuslar va yo\'nalishli taksilar','Автобусы и маршрутные такси','Автобуслар ва йўналишли таксилар',0),(@qid,'Tramvaylar va trolleybuslar','Трамваи и троллейбусы','Трамвайлар ва троллейбуслар',0),(@qid,'Belgilangan yo\'nalishlar bo\'yicha harakatlanadigan avtobuslar, trolleybuslar, tramvaylar va yo\'nalishli taksilar','Автобусы, троллейбусы, трамваи и маршрутные такси, движущиеся по установленным маршрутам','Белгиланган йўналишлар бўйича ҳаракатланадиган автобуслар, троллейбуслар, трамвайлар ва йўналишли таксилар',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('«Gazel» yuk avtomobilining yuk bilan balandligi yo\'l ustidan 3,8 m bo\'lsa, uni tashish mumkinmi?','Разрешается ли перевозка груза на грузовом автомобиле «Газель» без соблюдения специальных правил, если высота автомобиля с грузом составляет 3,8 м от поверхности дороги?','«Газель» юк автомобилининг юк билан баландлиги йўл устидан 3,8 м бўлса, уни ташиш мумкинми?','Юк ташиш',NULL,NULL,NULL,NULL,'ptest',26,8);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ruxsat beriladi','Разрешается','Рухсат берилади',1),(@qid,'Ruxsat berilmaydi','Запрещается','Рухсат берилмайди',0),(@qid,'Ruxsat beriladi, faqat yo\'nalishlarda osma ko\'priklar, osma yo\'l (estakada) bo\'lmasa','Только по дорогам, на которых отсутствует необходимость двигаться под мостами или путепроводами','Рухсат берилади, фақат йўналишларда осма кўприклар, осма йўл (эстакада) бўлмаса',0);
