INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Yuk transport vositasining o\'lchamlaridan chiqib tursa, kunning qorong\'i vaqtida va yetarli ko\'rinmaydigan sharoitda qanday belgilanadi?','Как обозначается груз, выступающий за габариты транспортного средства в темное время суток и в условиях недостаточной видимости?','Юк транспорт воситасининг ўлчамларидан чиқиб турса, куннинг қоронғи вақтида ва етарли кўринмайдиган шароитда қандай белгиланади?','Юк ташиш',NULL,NULL,NULL,NULL,'ptest',26,11);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Ishora taxtachalari yoki bayroqchalar (diagonal bo\'yicha navbatma-navbat tortilgan qizil va oq yo\'lli) bilan','Сигнальными щитками или флажками (с нанесенными по диагонали красными и белыми чередующими полосами)','Ишора тахтачалари ёки байроқчалар (диагонал бўйича навбатма-навбат тортилган қизил ва оқ йўлли) билан',0),(@qid,'«Катта ўлчамли юк» taniqlik belgisi bilan belgilanishi, qo\'shimcha ravishda oldiga oq, orqasiga esa qizil chiroqlar yoki yorug\'lik qaytargich bilan','«Негабаритного груза» опознавательным знаком, кроме того Светоотражающими приспособлениями или фонарями спереди белого, сзади красного','«Катта ўлчамли юк» таниқлик белгиси билан белгиланиши, қўшимча равишда олдига оқ, орқасига эса қизил чироқлар ёки ёруғлик қайтаргич билан',1),(@qid,'Orqasiga qizil, oldiga oq bayroqchalar bilan','Флажками – сзади красными, спереди белыми','Орқасига қизил, олдига оқ байроқчалар билан',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Bu yo\'l belgisi bilan belgilangan yo\'l qismida yengil avtomobilni shatakka olishga ruxsat etiladimi?','Разрешается ли буксировка легкового автомобиля на участке дороги; обозначенном этим дорожным знаком?','Бу йўл белгиси билан белгиланган йўл қисмида енгил автомобилни шатакка олишга рухсат этиладими?','Тақиқловчи белгилар','pt_c67dfca37fc0a9fb.webp',NULL,NULL,NULL,'ptest',26,12);
