INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Tramvayga chapga yoki to\'g\'riga','Трамваю налево или прямо','Трамвайга чапга ёки тўғрига',0),(@qid,'Faqat avtomobilga chapga','Только автомобилю налево','Фақат автомобилга чапга',0),(@qid,'Tramvay va avtomobilga chapga','Трамваю и автомобилю налево','Трамвай ва автомобилга чапга',0),(@qid,'Tramvayga chapga yoki to\'g\'riga, avtomobilga tramvaydan so\'ng','Трамваю налево или прямо, автомобилю после трамвая','Трамвайга чапга ёки тўғрига, автомобилга трамвайдан сўнг',0),(@qid,'Tramvayga chapga, avtomobilga chapga va teskari yo\'nalishga','Трамваю налево, автомобилю налево и в обратном направлении','Трамвайга чапга, автомобилга чапга ва тескари йўналишга',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Harakat tezligi 40 km/sdan oshmaydigan transport vositasiga qatnov qismining chap tasmasiga chiqishga qachon ruxsat etiladi?','В каких случаях разрешается выезжать за пределы правой полосы, если Вы управляете транспортным средством, скорость которого по техническим причинам не может быть более 40 км/ч?','Ҳаракат тезлиги 40 км/сдан ошмайдиган транспорт воситасига қатнов қисмининг чап тасмасига чиқишга қачон рухсат этилади?','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви','pt_1ef8e38692593169.webp',NULL,NULL,NULL,'ptest',26,14);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Burilish yoki qayrilish oldidan qayta tizilishda','Только при перестроении перед поворотом налево либо разворотом','Бурилиш ёки қайрилиш олдидан қайта тизилишда',0),(@qid,'Quvib o‘tishda, o‘zib ketishda yoki aylanib o‘tishda','Только при обгоне или объезде','Қувиб ўтишда, ўзиб кетишда ёки айланиб ўтишда',0),(@qid,'Sanab o‘tilgan barcha hollarda','Во всех перечисленных случаях','Санаб ўтилган барча ҳолларда',1),(@qid,'Sanab o‘tilgan barcha hollarda, shuningdek, agar bir yo‘nalishda harakatlanish uchun uchta va undan ortiq tasma bo‘lganda','Во всех перечисленных случаях, а также при наличии трех и более полос для движения в одном направлении','Санаб ўтилган барча ҳолларда, шунингдек, агар бир йўналишда ҳаракатланиш учун учта ва ундан ортиқ тасма бўлганда',0);
