INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar pnevmatik uzatmaning zichligi buzilib, kompressor ishlamay turganda boshqaruv asboblarining erkin holatida havo bosimining 30 daqiqada qancha MPa-ga pasayishiga sabab bo\'lsa, tormoz tizimi nosoz hisoblanadi?','Тормозная система считается неисправной, если нарушена герметичность пневматического привода, что вызывает падение давления воздуха при неработающем компрессоре за 30 мин, при свободном положении органов управления в МПа, более чем:','Агар пневматик узатманинг зичлиги бузилиб, компрессор ишламай турганда бошқарув асбобларининг эркин ҳолатида ҳаво босимининг 30 дақиқада қанча МПа-га пасайишига сабаб бўлса, тормоз тизими носоз ҳисобланади?','Транспорт воситаларидан фойдаланишни тақиқловчи шартлар',NULL,NULL,NULL,NULL,'ptest',26,16);
