INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Egallagan harakatlanish bo\'lagidan chiqib oldinda ketayotgan transport vositasidan o\'zib ketish','Опережение одного или нескольких транспортных средств другим связанное с выездом из занимаемой полосы','Эгаллаган ҳаракатланиш бўлагидан чиқиб олдинда кетаётган транспорт воситасидан ўзиб кетиш',0),(@qid,'Bir yoki bir nechta transport vositalarini qarama-qarshi yo\'nalishda harakatlanish uchun mo\'ljallangan tasmaga chiqib, so\'ngra ilgari egallagan qatoriga qaytib o\'tish bilan bog\'liq bo\'lgan o\'zib ketish','Опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения и последующим возвращением на ранее занимаемую полосу','Бир ёки бир нечта транспорт воситаларини қарама-қарши йўналишда ҳаракатланиш учун мўлжалланган тасмага чиқиб, сўнгра илгари эгаллаган қаторига қайтиб ўтиш билан боғлиқ бўлган ўзиб кетиш',1),(@qid,'Kam tezlik bilan qo\'shni qatorda harakatlanayotgan bir yoki bir qancha transport vositalaridan o\'zib ketish','Опережение одного или нескольких транспортных средств движущихся в соседнем ряду с меньшей скоростью','Кам тезлик билан қўшни қаторда ҳаракатланаётган бир ёки бир қанча транспорт воситаларидан ўзиб кетиш',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Avtomobillar chorrahani quyidagi tartibda kesib o\'tadilar:','Автомобили проедут перекресток в следующем порядке:','Автомобиллар чорраҳани қуйидаги тартибда кесиб ўтадилар:','Тартибга солинмаган чорраҳалар тенг ахамиятли','pt_ef37b2fb53e71a51.webp',NULL,NULL,NULL,'ptest',27,9);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Sariq chorrahaga chiqadi va yashilni o‘tkazib yuborish uchun to‘xtaydi; yashil, ko‘k ayni vaqtda qizil bilan, sariq','Желтый въедет на перекресток и останавливается, чтобы пропустить зеленый, зеленый, синий одновременно красный, желтый','Сариқ чорраҳага чиқади ва яшилни ўтказиб юбориш учун тўхтайди; яшил, кўк айни вақтда қизил билан, сариқ',0),(@qid,'Ko\'k, ayni vaqtda qizil bilan, yashil, sariq','Синий одновременно с красным, зеленый, желтый','Кўк, айни вақтда қизил билан, яшил, сариқ',0),(@qid,'Yashil, ko\'k ayni vaqtda qizil, so\'ng sariq','Зеленый, синий одновременно с красным, желтый','Яшил, кўк айни вақтда қизил, сўнг сариқ',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Bu belgida harakatlanish ruxsat etiladi:','При этом знаке разрешено движение:','Бу белгида ҳаракатланиш рухсат этилади:','Буюрувчи белгилар','pt_581e3b1dcc8157f6.webp',NULL,NULL,NULL,'ptest',27,10);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Faqat avtomobil haydovchisiga','Только водителю автомобиля','Фақат автомобил ҳайдовчисига',0),(@qid,'Faqat avtomobil va mototsikl haydovchilariga','Только водителям автомобиля и мотоцикла','Фақат автомобил ва мотоцикл ҳайдовчиларига',0),(@qid,'Barcha transport vositalarining haydovchilariga','Водителям всех транспортных средств','Барча транспорт воситаларининг ҳайдовчиларига',1),(@qid,'Faqat avtomobil va avtobus haydovchilariga','Только водителям автомобиля и автобуса','Фақат автомобил ва автобус ҳайдовчиларига',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Chiziqlar bilan bo\'laklarga ajratilgan yo\'lning qatnov qismida transport vositalarining harakatlanishi qanday amalga oshirilishi kerak?','Как должно осуществляется движения транспортных средств на дорогах проезжая часть которых разделена на полосы линиями разметки?','Чизиқлар билан бўлакларга ажратилган йўлнинг қатнов қисмида транспорт воситаларининг ҳаракатланиши қандай амалга оширилиши керак?','Ҳаракатланишни бошлаш, манёвр қилиш',NULL,NULL,NULL,NULL,'ptest',27,11);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qatiy bo\'laklar bo\'yicha, uzuq-uzuq chiziqni kesib o\'tishga faqat qayta tizilishda ruxsat etiladi','Строго по полосам. Наезжать на прерывистые линии разметки разрешается лишь при перестроении','Қатъий бўлаклар бўйича, узуқ-узуқ чизиқни кесиб ўтишга фақат қайта тизилишда рухсат этилади',1),(@qid,'Agar qatnov qismi transport vositalaridan xoli bo\'lsa, bo\'lak bo\'yicha qatiy emas','Не строго по полосам, если проезжая часть свободна от транспортных средств','Агар қатнов қисми транспорт воситаларидан холи бўлса, бўлак бўйича қатъий эмас',0),(@qid,'Agar transport vositalarining o\'lchamlari eniga katta bo\'lmasa, bo\'lak bo\'yicha qatiy emas','Не строго по полосам, если габариты транспортных средств по ширине не велики','Агар транспорт воситаларининг ўлчамлари энига катта бўлмаса, бўлак бўйича қатъий эмас',0),(@qid,'Agar qatnov qismida tirkamali avtomobillar bo\'lmasa va bunda ancha tor harakat oralig\'ini saqlash mumkin bo\'lsa, bo\'laklar bo\'yicha qatiy emas','Не строго по полосам, если на проезжей части отсутствуют автомобили с прицепами и при этом интервал движения можно соблюдать гораздо меньший','Агар қатнов қисмида тиркамали автомобиллар бўлмаса ва бунда анча тор ҳаракат оралиғини сақлаш мумкин бўлса, бўлаклар бўйича қатъий эмас',0);
