INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Zanjirli bo\'lgan qishloq xo\'jalik, yo\'l qurilishi va mexanik transport vositalariga temir yo\'l kesishmasidan o\'tishga ruxsat etiladimi?','Разрешается ли переезжать через железнодорожный переезд сельскохозяйственным, дорожным и строительным механическим транспортным средствам на гусеничном ходу?','Занжирли бўлган қишлоқ хўжалик, йўл қурилиши ва механик транспорт воситаларига темир йўл кесишмасидан ўтишга рухсат этиладими?','Темир йўл кесишмалари орқали ҳаракатланиш',NULL,NULL,NULL,NULL,'ptest',28,14);
