INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Aholi yashaydigan joylardan tashqarida transport vositalarining uzoq to\'xtab turishi (dam olishi, tunash va hokazo)ga qayerda ruxsat etiladi?','Где разрешается длительная стоянка транспортных средств (отдых, ночлег и т.д.) вне населенного пункта?','Аҳоли яшайдиган жойлардан ташқарида транспорт воситаларининг узоқ тўхтаб туриши (дам олиши, тунаш ва ҳоказо)га қаерда рухсат этилади?','Тўхташ ва тўхтаб туриш',NULL,NULL,NULL,NULL,'ptest',28,15);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'l chetida','На обочине дороге','Йўл четида',0),(@qid,'To\'xtab turish maydonchalarida yoki yo\'ldan tashqarida','На площадках для стоянки или за пределами дороги','Тўхтаб туриш майдончаларида ёки йўлдан ташқарида',1),(@qid,'Yo\'l qatnov qismining o\'ng tomonida, biroq boshqa transport vositalarining harakatlanishiga to\'sqinlik qilmasligi kerak','На правой стороне проезжей части дороги, но так чтобы не препятствовать движению других транспортных средств','Йўл қатнов қисмининг ўнг томонида, бироқ бошқа транспорт воситаларининг ҳаракатланишига тўсқинлик қилмаслиги керак',0),(@qid,'Yo\'lning chap tomonida, biroq harakat xafvsizligi choralariga rioya qilgan holda','На левой стороне, только соблюдая все меры безопасности движения','Йўлнинг чап томонида, бироқ ҳаракат хафвсизлиги чораларига риоя қилган ҳолда',0);
