INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Shaharlararo qatnaydigan avtobusning haydovchisiga aholi punktlaridan tashqarida tezlikni 80 km/soat dan oshirishga ruxsat etiladimi?','Разрешается ли водителю междугородного автобуса вне населенных пунктов превышать скорость 80 км/ч?','Шаҳарлараро қатнайдиган автобуснинг ҳайдовчисига аҳоли пунктларидан ташқарида тезликни 80 км/соат дан оширишга рухсат этиладими?','Ҳаракатланиш тезлиги',NULL,NULL,NULL,NULL,'ptest',28,20);
