INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'«С» toifadagi transport vositasini boshqarish huquqi guvohnomasi bo\'lib, shu avtomobilda uch yillik ish davriga ega bo\'lgan haydovchilarga','Водителям, имеющим удостоверение на право управления транспортным средством категории «С» с трехлетним стажем работы на данном автомобиле','«С» тоифадаги транспорт воситасини бошқариш ҳуқуқи гувоҳномаси бўлиб, шу автомобилда уч йиллик иш даврига эга бўлган ҳайдовчиларга',0),(@qid,'«D» va «С» toifadagi transport vositalarini boshqarish huquqiga ega bo\'lgan va shu toifadagi transport vositalaridan birini 3 yildan ortiq boshqargan haydovchilarga','Водителям имеющим удостоверение на право управления транспортными средствами категории «D» и «С» и стаж управления транспортными средствами одной из этих категорий более 3-х лет','«D» ва «С» тоифадаги транспорт воситаларини бошқариш ҳуқуқига эга бўлган ва шу тоифадаги транспорт воситаларидан бирини 3 йилдан ортиқ бошқарган ҳайдовчиларга',1);
