INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Qaysi qo\'shimcha axborot belgisi transport vositalarini to\'xtab turish joyiga qo\'yish usulini ko\'rsatadi?','Какой знак указывает способ постановки транспортного средства на стоянку?','Қайси қўшимча ахборот белгиси транспорт воситаларини тўхтаб туриш жойига қўйиш усулини кўрсатади?','Қўшимча ахборот белгилари','pt_43ddcb72935da836.webp',NULL,NULL,NULL,'ptest',29,3);
