INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'l qo\'yiladi, agar bu piyodalarning harakatiga xalal bermasa','Допускается, если это не затрудняет движение пешеходов','Йўл қўйилади, агар бу пиёдаларнинг ҳаракатига халал бермаса',0),(@qid,'Yo\'l qo\'yilmaydi, chunki bu piyodalarning hayotini xavf ostiga qo\'yishi mumkin','Не допускается, так как это может поставить под угрозу безопасность пешеходов','Йўл қўйилмайди, чунки бу пиёдаларнинг ҳаётини хавф остига қўйиши мумкин',0),(@qid,'Bevosita shu trotuar yoki yo\'lkalarda joylashgan savdo yoki boshqa korxonalarga xizmat ko\'rsatishda yo\'l qo\'yiladi','Допускается при обслуживании торговых и других предприятий расположенных непосредственно у этих тротуаров или дорожек','Бевосита шу тротуар ёки йўлкаларда жойлашган савдо ёки бошқа корхоналарга хизмат кўрсатишда йўл қўйилади',1),(@qid,'Trotuarda turgan boshqa transport vositasini aylanib o\'tish uchun yo\'l qo\'yiladi','Допускается для объезда стоящего у тротуара другого транспортного средства','Тротуарда турган бошқа транспорт воситасини айланиб ўтиш учун йўл қўйилади',0);
