INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Shinalar o\'lchami va yo\'l qo\'yiladigan bosimi bo\'yicha transport vositasining rusumiga mos emas','Шины по размеру и допустимой нагрузке не соответствуют модели транспортного средства','Шиналар ўлчами ва йўл қўйиладиган босими бўйича транспорт воситасининг русумига мос эмас',0),(@qid,'Transport vositasining bitta o\'qiga diaganal shinalar radial shinalar bilan birga o\'rnatilgan','На одну ось транспортного средства установлены диагональные шины совместно с радиальными','Транспорт воситасининг битта ўқига диаганал шиналар радиал шиналар билан бирга ўрнатилган',0),(@qid,'M1 toifadagi avtotransport vositalarining oldingi o\'qiga birinchi toifada tamirlangan shinalar o\'rnatilgan','На переднюю ось легкового автомобиля категории М1 установлены шины, восстановленные по первому классу ремонта','М1 тоифадаги автотранспорт воситаларининг олдинги ўқига биринчи тоифада таъмирланган шиналар ўрнатилган',1);
