INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Transport vositasi texnik tavsifnomasida ko\'rsatilgan yuqori tezlikdan oshirilishi mumkinmi?','Может ли быть повышена максимальная скорость движения; определенная технической характеристикой транспортного средства?','Транспорт воситаси техник тавсифномасида кўрсатилган юқори тезликдан оширилиши мумкинми?','Ҳаракатланиш тезлиги',NULL,NULL,NULL,NULL,'ptest',32,3);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'llardan foydalanish uchun masul bo\'lgan idoralar tomonidan oshirilishi mumkin','Может быть повышена органами; ответственными за эксплуатацию дорог','Йўллардан фойдаланиш учун масъул бўлган идоралар томонидан оширилиши мумкин',0),(@qid,'Aholi yashaydigan joylardan tashqaridagi yo\'llarda oshirilishi mumkin. Bunday yo\'l qismlarida «юқори тезлик чекланган» belgisi o\'rnatiladi','Может быть повышена на дорогах вне населенных пунктов. На таких участках устанавливаются знаки \"Ограничение максимальной скорости\"','Аҳоли яшайдиган жойлардан ташқаридаги йўлларда оширилиши мумкин. Бундай йўл қисмларида «юқори тезлик чекланган» белгиси ўрнатилади',0),(@qid,'Oshirilishi mumkin emas','Не может быть превышена','Оширилиши мумкин эмас',1);
