INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'lning qatnov qismining chetki o\'ng bo\'lagida','На крайней правой полосе проезжей части',NULL,0),(@qid,'Yo\'lning 100 m dan ko\'proq qismi ko\'rinadigan va harakat bo\'laklari soni to\'rttadan ortiq bo\'lgan joylarda','В местах, где дорога просматривается более чем на 100 м и число полос движения больше четырёх',NULL,0),(@qid,'To\'xtab turish uchun «Тўхтаб туриш жойи» yoki «Дам олиш жойи» belgilari bilan belgilangan maxsus maydonchalarda','На специальных площадках для стоянки, обозначенных знаками «Место стоянки» или «Место отдыха»',NULL,1);
