INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Tartibga solingan chorrahalarda','На регулируемых перекрёстках',NULL,0),(@qid,'Chorrahalardan tashqarida, agar qatnov qismining kengligi chetki chap holatdan qayrilish uchun yetarli bo\'lmasa','Вне перекрёстков, если ширина проезжей части недостаточна для разворота из крайнего левого положения',NULL,1),(@qid,'Tartibga solinmaydigan chorrahalarda, agar qayrilishni amalga oshirayotgan transport vositasi asosiy yo\'lda bo\'lsa','На нерегулируемых перекрёстках, если разворачивающееся транспортное средство находится на главной дороге',NULL,0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar transport vositasida «Tezlik cheklangan» taniqli belgisi o‘rnatilgan bo‘lsa, bu transport vositasining haydovchisiga:','Если на транспортном средстве установлен опознавательный знак «ограничения скорости», водитель транспортного средства обязан:','Агар транспорт воситасида «Тезлик чекланган» таниқли белгиси ўрнатилган бўлса, бу транспорт воситасининг ҳайдовчисига:','Ҳаракатланиш тезлиги',NULL,NULL,NULL,NULL,'ptest',32,16);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Belgida ko\'rsatilgan tezlikdan oshirishga faqat tezlik tegishli yo\'l belgisi o\'rnatilib oshirilgan yo\'l qismlarida ruxsat beriladi','Разрешается превышать указанную на знаке скорость только на участках дорог где скорость движения повышена установкой соответствующего дорожного знака','Белгида кўрсатилган тезликдан оширишга фақат тезлик тегишли йўл белгиси ўрнатилиб оширилган йўл қисмларида рухсат берилади',0),(@qid,'Belgida ko\'rsatilgan tezlikdan oshirish taqiqlanadi','Запрещается превышать указанную на знаке скорость','Белгида кўрсатилган тезликдан ошириш тақиқланади',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Avtopoyezdning belgisi qanday holda yoqilgan bo\'lishi kerak?','Знак автопоезда должен быть включен:','Автопоезднинг белгиси қандай ҳолда ёқилган бўлиши керак?','Ташқи ёритиш асбобларидан фойдаланиш',NULL,NULL,NULL,NULL,'ptest',32,17);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Tunda yoki etarli ko\'rinmaydigan sharoitda harakat qilganda','При движении ночью или в условиях недостаточной видимости','Тунда ёки етарли кўринмайдиган шароитда ҳаракат қилганда',0),(@qid,'Faqat avtopoyezd harakat qilganda','Только при движении автопоезда','Фақат автопоезд ҳаракат қилганда',0),(@qid,'Avtopoyezd harakat qilganda, shuningdek, qorong\'i vaqtida to\'xtaganda va to\'xtab turganida','При движении автопоезда, а также при его остановке и стоянке в темное время суток','Автопоезд ҳаракат қилганда, шунингдек, қоронғи вақтида тўхтаганда ва тўхтаб турганида',1),(@qid,'Faqat avtopoyezd yuk bilan harakat qilganda','Только при движении автопоезда с грузом','Фақат автопоезд юк билан ҳаракат қилганда',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Aholi yashaydigan yo\'llardan tashqarida yo\'lning qatnov qismida haydovchilar transport vositalarini qayerda harakatlantirishlari kerak?','Где на проезжей части вне населенных пунктов водители должны вести транспортные средства?','Аҳоли яшайдиган йўллардан ташқарида йўлнинг қатнов қисмида ҳайдовчилар транспорт воситаларини қаерда ҳаракатлантиришлари керак?','Йўлнинг қатнов қисмида транспорт воситаларининг жойлашуви',NULL,NULL,NULL,NULL,'ptest',32,18);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Iloji boricha qatnov qismining o\'ng chetiga yaqinroq joyda','По возможности ближе к правому краю проезжей части','Иложи борича қатнов қисмининг ўнг четига яқинроқ жойда',1),(@qid,'Xohlagan bo\'lak bo\'ylab','По любой полосе','Хоҳлаган бўлак бўйлаб',0),(@qid,'Faqat o\'ng bo\'lak bo\'ylab. Chap bo\'lak o\'tish faqat chapga burish va burilish uchun ruxsat etiladi','Только по правой полосе. Выезд на левую полосу разрешается для поворота налево или разворота','Фақат ўнг бўлак бўйлаб. Чап бўлак ўтиш фақат чапга буриш ва бурилиш учун рухсат этилади',0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Quvib o\'tish qaysi hollardan taqiqlanadi?','Обгон запрещается?','Қувиб ўтиш қайси ҳоллардан тақиқланади?','Қувиб ўтиш',NULL,NULL,NULL,NULL,'ptest',32,19);
