INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Agar yo\'l-transport hodisasi natijasida hech kim jabrlanmasa, moddiy zarar esa ahamiyatsiz bo\'lsa, haydovchilarning o\'zlari hodisa ro\'y bergan joyni tark etib, DYHXXning eng yaqin yoki IIO idorasiga hodisani qayd qilish uchun bora oladilarmi?','Если в результате дорожно-транспортного происшествия нет пострадавших, а материальный ущерб несущественен, могут ли водители сами покинуть место происшествия и прибыть на ближайший пост ГСБДД или в органы внутренних дел для оформления происшествия?','Агар йўл-транспорт ҳодисаси натижасида ҳеч ким жабрланмаса, моддий зарар эса аҳамиятсиз бўлса, ҳайдовчиларнинг ўзлари ҳодиса рўй берган жойни тарк этиб, ДЙҲХХнинг энг яқин ёки ИИО идорасига ҳодисани қайд қилиш учун бора оладиларми?','Ҳайдовчиларнинг умумий вазифалари',NULL,NULL,NULL,NULL,'ptest',33,13);
