INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'40 km/soat dan kam tezlikda ketayotgan yakka, yon kajavasi bo\'lmagan ikki g\'ildirakli mototsikllar va velosipedlardan tashqari barcha mexanik transport vositalarini quvib o\'tish taqiqlanadi','Запрещается обгонять все механические транспортные средства, кроме одиночных, движущихся со скоростью менее 40 км/ч, двухколесных мотоциклов без бокового прицепа и велосипедов','40 км/соат дан кам тезликда кетаётган якка, ён кажаваси бўлмаган икки ғилдиракли мотоцикллар ва велосипедлардан ташқари барча механик транспорт воситаларини қувиб ўтиш тақиқланади',0),(@qid,'Ruxsat etilgan to\'la vazni 3,5 t dan ziyod bo\'lgan yuk avtomobili bilan 40 km/soat dan kam tezlikda ketayotgan yakka transport vositalaridan tashqari barcha transport vositalarini quvib o\'tish taqiqlanadi','Грузовым автомобилям, разрешенная максимальная масса которых превышает 3,5 т, запрещается обгонять все транспортные средства, кроме одиночных, движущихся со скоростью менее 40 км/ч','Рухсат этилган тўла вазни 3,5 т дан зиёд бўлган юк автомобили билан 40 км/соат дан кам тезликда кетаётган якка транспорт воситаларидан ташқари барча транспорт воситаларини қувиб ўтиш тақиқланади',1);
