INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'«Ногирон» taniqli belgisi bo\'lgan avtomobillar uchun 30 m dan keyin to\'xtab turish joyiga kelishini','Знак «Инвалид» для автомобилей с ограниченными возможностями появится на проезжей части через 30 м','«Ногирон» таниқли белгиси бўлган автомобиллар учун 30 м дан кейин тўхтаб туриш жойига келишини',0),(@qid,'Motokajavalardan tashqari transport vositalari uchun 30 m li hududdagi to\'xtab turish joyini','Место стоянки в зоне 30 м для транспортных средств, кроме мотоколясок','Мотокажавалардан ташқари транспорт воситалари учун 30 м ли ҳудуддаги тўхтаб туриш жойини',0),(@qid,'«Ногирон» taniqli belgisi bo\'lgan motokajava va avtomobillar uchun 30 m li hududdagi to\'xtab turish joyini','Место стоянки в зоне 30 м для мотоколясок и автомобилей с опознавательным знаком «Инвалид»','«Ногирон» таниқли белгиси бўлган мотокажава ва автомобиллар учун 30 м ли ҳудуддаги тўхтаб туриш жойини',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Yuk avtomobili haydovchisi rasmda ko\'rsatilgan holatda maxsus tovush ishorasini eshitib yoki miltillovchi ishorani ko\'rib nima qilishi kerak?','Что должен сделать водитель грузового автомобиля в случае; когда он слышит специальный звуковой сигнал и видит проблесковый маячок?','Юк автомобили ҳайдовчиси расмда кўрсатилган ҳолатда махсус товуш ишорасини эшитиб ёки милтилловчи ишорани кўриб нима қилиши керак?','Махсус транспорт воситаларининг имтиёзлари','pt_0335284bdbc859aa.webp',NULL,NULL,NULL,'ptest',34,13);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qatnov qismidagi o\'z bo\'lagi bo\'ylab harakatni davom ettirish','Продолжать свое движение по полосе','Қатнов қисмидаги ўз бўлаги бўйлаб ҳаракатни давом эттириш',0),(@qid,'Haydovchi maxsus tovushli ishoralarini yoqqan holda yaqinlashib kelayotgan transport vositalariga yo\'l berishlari, zarur bo\'lgan hollarda ularning to\'siqsiz o\'tib ketishlari uchun o\'zlarini yo\'lning o\'ng tomoniga olib to\'xtashlari shart','Водитель при приближении специального транспортного средства с включенными проблесковым маячком и специальным звуковым сигналом, обязан уступить им дорогу, при необходимости остановиться у правого края проезжей части','Ҳайдовчи махсус товушли ишораларини ёққан ҳолда яқинлашиб келаётган транспорт воситаларига йўл беришлари, зарур бўлган ҳолларда уларнинг тўсиқсиз ўтиб кетишлари учун ўзларини йўлнинг ўнг томонига олиб тўхташлари шарт',1);
