INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Kuzov (kabina) qismlari va bo\'yog\'iga tashqi tomondan anchagina shikast etgan bo\'lsa','Имеются значительные внешние повреждения деталей кузова (кабины) и окраски','Кузов (кабина) қисмлари ва бўёғига ташқи томондан анчагина шикаст етган бўлса',0),(@qid,'Ulagich moslamasi nosoz bo\'lsa (avtopoyezd tarkibida)','Неисправно сцепное устройство (в составе автопоезда)','Улагич мосламаси носоз бўлса (автопоезд таркибида)',1),(@qid,'Kuzov (kabina) qismlari va bo\'yog\'iga tashqi tomondan anchagina shikast etgan bo\'lsa hamda ressoralarning o\'zak qatlami yoki markaziy bolti shikastlangan hollarda','При наличии значительных внешних повреждений деталей кузова (кабины) и лакокрасочного покрытия, а также в случаях повреждения коренного листа или центрального болта рессор','Кузов (кабина) қисмлари ва бўёғига ташқи томондан анчагина шикаст етган бўлса ҳамда рессораларнинг ўзак қатлами ёки марказий болти шикастланган ҳолларда',0);
