INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Bir va bir necha transport vositalaridan o\'zib ketish','Опережение одного или нескольких транспортных средств','Бир ва бир неча транспорт воситаларидан ўзиб кетиш',0),(@qid,'Egallab turgan bo\'lakdan qarama qarshi harakat bo\'lagiga chiqib bir yoki bir necha transport vositalaridan o\'zib ketish va dastlab egallab turgan bo\'lagiga qaytish','Опережение одного или нескольких транспортных средств, связанное с выездом на полосу (сторону проезжей части), предназначенную для встречного движения, и последующим возвращением на ранее занимаемую полосу (сторону проезжей части)','Эгаллаб турган бўлакдан қарама қарши ҳаракат бўлагига чиқиб бир ёки бир неча транспорт воситаларидан ўзиб кетиш ва дастлаб эгаллаб турган бўлагига қайтиш',1),(@qid,'Egallagan harakatlanish bo\'lagidan chiqib, oldinda harakatlanayotgan transport vositasidan o\'zib ketish','Опережение движущегося впереди транспортного средства, связанное с выездом из занимаемой полосы','Эгаллаган ҳаракатланиш бўлагидан чиқиб, олдинда ҳаракатланаётган транспорт воситасидан ўзиб кетиш',0);
