INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Yo\'lning keskin burilishida yuzaga keladigan sirpanishning oldini olish uchun haydovchi nima qilishi kerak?','Что следует сделать водителю, чтобы предотвратить возникновение заноса при проезде крутого поворота?','Йўлнинг кескин бурилишида юзага келадиган сирпанишнинг олдини олиш учун ҳайдовчи нима қилиши керак?','Ҳаракат хафсизлиги асослари',NULL,NULL,NULL,NULL,'ptest',39,12);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Burilishdan oldin tezlikni kamaytirib, avtomobilni erkin harakatlanishi uchun ilashma tepkisini bosishi','Перед поворотом снизить скорость и выжать педаль сцепления, чтобы дать возможность автомобилю двигаться накатом на повороте','Бурилишдан олдин тезликни камайтириб, автомобилни эркин ҳаракатланиши учун илашма тепкисини босиши',0),(@qid,'Burilishdan oldin tezlikni kamaytirish, kerak bo\'lsa uzatmalar pag\'onasini pasaytirish, burilishdan o\'tayotganda tezlikni oshirmaslik va avtomobilni keskin tormozlamaslik','Перед поворотом снизить скорость, при необходимости включить пониженную передачу, а при проезде поворота не увеличивать резко скорость и не тормозить.','Бурилишдан олдин тезликни камайтириш, керак бўлса узатмалар пағонасини пасайтириш, бурилишдан ўтаётганда тезликни оширмаслик ва автомобилни кескин тормозламаслик',1),(@qid,'Sanab o\'tilan ikkisiga ham ruxsat etiladi','Допускается любое из перечисленных действий','Санаб ўтилан иккисига ҳам рухсат этилади',0);
