INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'l qatnov qismining piyodalar kesib o\'tishi uchun mo\'ljallangan, 5.16.1, 5.16.2 yo\'l belgilari va 1.14.1-1.14.3 yo\'l chiziqlari bilan ajratilgan bo\'lagi.','Часть участка дороги, предназначенная для движения пешеходов, отделенная знаками 5.16.1, 5.16.2 и дорожной разметкой 1.14.1-1.14.3.','Йўл қатнов қисмининг пиёдалар кесиб ўтиши учун мўлжалланган, 5.16.1, 5.16.2 йўл белгилари ва 1.14.1-1.14.3 йўл чизиқлари билан ажратилган бўлаги.',0),(@qid,'Yo\'lning piyodalar harakatlanishi uchun mo\'ljallangan va transport vositalari harakati taqiqlangan qismi','Участок дороги, предназначенный для пешеходов и движения транспортных средств, запрещен.','Йўлнинг пиёдалар ҳаракатланиши учун мўлжалланган ва транспорт воситалари ҳаракати тақиқланган қисми',1),(@qid,'Qatnov qismiga tutashgan yoki undan maysazor, ariq maxsus to\'siqlar bilan ajratilgan va piyodalarning harakatlanishi uchun mo\'ljallangan yo\'l qismi','Часть дороги, примыкающая к проезжей части или отделенная от нее газоном, арыком, специальными ограждениями и предназначенная для движения пешеходов.','Қатнов қисмига туташган ёки ундан майсазор, ариқ махсус тўсиқлар билан ажратилган ва пиёдаларнинг ҳаракатланиши учун мўлжалланган йўл қисми',0);
