INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'l qatnov qismining piyodalar kesib o\'tishi mo\'ljallangan, 5.16.1, 5.16.2 yo\'l belgilari va 1.14.1-1.14.3 yo\'l chiziqlari bilan ajratilgan bo\'lagi.','Часть участка дороги, предназначенная для пешеходного перехода с дорожными знаками 5.16.1, 5.16.2 и дорожными полосами 1.14.1-1.14.3.','Йўл қатнов қисмининг пиёдалар кесиб ўтиши мўлжалланган, 5.16.1, 5.16.2 йўл белгилари ва 1.14.1-1.14.3 йўл чизиқлари билан ажратилган бўлаги.',1),(@qid,'Yo\'lning piyodalar harakatlanishi uchun mo\'ljallangan va transport vositalari harakati taqiqlangan qismi.','Часть дороги, предназначенная для пешеходного движения и запрещенная для движения транспортных средств.','Йўлнинг пиёдалар ҳаракатланиши учун мўлжалланган ва транспорт воситалари ҳаракати тақиқланган қисми.',0),(@qid,'Qatnov qismiga tutashgan yoki undan maysazor ariq maxsus to\'siqlar bilan ajratilgan va piyodalarning va piyodalarning harakatlanishi uchun mo\'ljallangan yo\'l qismi','Часть дороги, примыкающая к проезжей части или отделенная от нее газоном, бордюром, специальными ограждениями и предназначенная для движения пешеходов.','Қатнов қисмига туташган ёки ундан майсазор ариқ махсус тўсиқлар билан ажратилган ва пиёдаларнинг ва пиёдаларнинг ҳаракатланиши учун мўлжалланган йўл қисми',0);
