INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Quyidagi izoh qaysi atamaga tegishli? Texnik nuqson, tashilayotgan yuk, haydovchi va yo\'lovchining holati, yo\'ldagi biror to\'siq tufayli xavf yuzaga kelganda yoxud ob-havo sharoitiga bog\'liq holda transport vositasi harakatini to\'xtatish','К какому термину относится следующее пояснения? Остановка движения транспортного средства из-за технической неисправности, перевозимого груза, состояния водителя и пассажиров, наличия препятствия на дороге или погодных условий.','Қуйидаги изоҳ қайси атамага тегишли? Техник нуқсон, ташилаётган юк, ҳайдовчи ва йўловчининг ҳолати, йўлдаги бирор тўсиқ туфайли хавф юзага келганда ёхуд об-ҳаво шароитига боғлиқ ҳолда транспор воситаси ҳаракатини тўхтатиш','Умумий қоидалар',NULL,NULL,NULL,NULL,'ptest',43,1);
