INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Temir yo\'l kesishmasiga yaqinlashganlik haqida','О приближении к железнодорожному переезду','Темир йўл кесишмасига яқинлашганлик ҳақида',0),(@qid,'Xavfli chorrahaga yaqinlashganlik haqida','О приближении к опасному перекрестку','Хавфли чорраҳага яқинлашганлик ҳақида',0),(@qid,'Yo\'lning kichik radiusli burilish, tik nishablik va boshqa xavfli joylarida yo\'l to\'siqlarining yon yuzalarini bildiradi','Обозначает боковые поверхности ограждения дорог на закруглениях малого радиуса крутых спусках и на других опасных участках','Йўлнинг кичик радиусли бурилиш, тик нишаблик ва бошқа хавфли жойларида йўл тўсиқларининг ён юзаларини билдиради',1);
