INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Haydovchi biron bir xavfni aniqlab, avtomobilni to\'liq to\'xtaguncha bosib o\'tgan masofasi','Расстояние, пройденное транспортным средством до полной остановки автомобиля после обнаружения опасности.','Ҳайдовчи бирон бир хавфни аниқлаб, автомобилни тўлиқ тўхтагунча босиб ўтган масофаси',0),(@qid,'Haydovchi tormoz tepkisini bosgandan to avtomobil to\'liq to\'xtaguncha bosib o\'tilgan masofa','Расстояние, пройденное транспортным средством с момента нажатия на педаль тормоза до полной остановки','Ҳайдовчи тормоз тепкисини босгандан то автомобил тўлиқ тўхтагунча босиб ўтилган масофа',1);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Yo\'lning xavfli burilishlarida oldingi uzatmali avtomobilning orqa o\'qi yon tomonga sirpanganda siz qanday harakat qilasiz?','Как вы будете действовать при заносе задней оси переднеприводного автомобиля на опасном повороте дороги?',NULL,NULL,NULL,NULL,NULL,NULL,'ptest',44,5);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Gaz berishni kamaytirib rul chambaragi bilan boshqaruvni barqarorlashtirasiz','Уменьшите подачу топлива и стабилизируете управление рулевым колесом',NULL,0),(@qid,'Tormozlab turib rul chambaragini sirpangan tomonga burasiz','Притормаживая, повернёте рулевое колесо в сторону заноса',NULL,0),(@qid,'Gaz pedalini ohista bosib, avtomobilni rul chambaragini to\'g\'rilab, avtomobilni sirpanishdan olib chiqib ketasiz','Плавно нажимая на педаль акселератора и выравнивая рулевое колесо, выведете автомобиль из заноса',NULL,1),(@qid,'Gaz pedalini ko\'proq bosib rul chambaragini o\'zgartirmasdan sirpanishdan olib chiqasiz','Сильнее нажав на педаль акселератора, выведете автомобиль из заноса, не меняя положения рулевого колеса',NULL,0);
INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Qorin bo\'shlig\'i jarohatlangan odamga ovqat, suv, dori-darmon berishi mumkinmi?','Можно ли давать еду, воду, лекарства человеку с травмой живота?','Қорин бўшлиғи жароҳатланган одамга овқат, сув, дори-дармон бериши мумкинми?','Биринчи тиббий ёрдам',NULL,NULL,NULL,NULL,'ptest',44,6);
