INSERT INTO `Questions` (`QuestionUZ`,`QuestionRU`,`QuestionUZK`,`Topic`,`ImageUrl`,`ExplanationUZ`,`ExplanationRU`,`ExplanationUZK`,`Source`,`BiletNumber`,`BiletOrder`) VALUES ('Bosh miya jarohatlanganda, miya chayqalganda yoki bo\'yin qismi jarohatlanganda birinchi yordam ko\'rsatish:','Первая помощь при травме головы, сотрясении мозга или травме шеи','Бош мия жароҳатланганда, мия чайқалганда ёки бўйин қисми жароҳатланганда биринчи ёрдам кўрсатиш:','Биринчи тиббий ёрдам',NULL,NULL,NULL,NULL,'ptest',44,7);
INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Jarohatlangan odamni qattiq va tekis zambilga solib, bo\'yin qismi tagiga qattiq yostiqcha qo\'yib, qo\'zg\'atmasdan, mahkam bog\'lab shifoxonaga yuboriladi','Пострадавшего кладут на жесткие и плоские носилки, под шею подкладывают подушку и без движения отправляют в больницу','Жароҳатланган одамни қаттиқ ва текис замбилга солиб, бўйин қисми тагига қаттиқ ёстиқча қўйиб, қўзғатмасдан, маҳкам боғлаб шифохонага юборилади',1),(@qid,'Jaroxatlangan odamni yonboshlatib yotqizib, bo\'yin qismi tagiga qattiq yostiqcha qo\'yib, qo\'zg\'atmasdan, mahkam bog\'lab shifoxonaga yuboriladi','Уложить пострадавшего на бок, подложить под шею твердую подушку, туго связать, не шевелясь, и отправиться в больницу','Жарохатланган одамни ёнбошлатиб ётқизиб, бўйин қисми тагига қаттиқ ёстиқча қўйиб, қўзғатмасдан, маҳкам боғлаб шифохонага юборилади',0),(@qid,'Jaroxatlangan odamni tinchlantirish, jarohatlangan joy sohasini sovuq suv muz qo\'yish yo\'llari bilan sovutish og\'riqni susaytirish va qon ketishini kamaytirish','Успокоить пострадавшего, охладить поврежденное место холодной водой или льдом, уменьшить боль и кровотечение','Жарохатланган одамни тинчлантириш, жароҳатланган жой соҳасини совуқ сув муз қўйиш йўллари билан совутиш оғриқни сусайтириш ва қон кетишини камайтириш',0);
