INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Bevosita yo\'lga tutashgan va transport vositalari o\'tib ketishi uchun mo\'ljallanmagan hudud (hovlilar, turar joy dahalari avtomobil to\'xtab turish joylari, yonilg\'i quyish shaxobchalari, korxona va shunga o\'xshashlar).','Территория, непосредственно прилегающая к дороге и не предназначенная для сквозного движения транспортных средств.','Бевосита йўлга туташган ва транспорт воситалари ўтиб кетиши учун мўлжалланмаган ҳудуд (ҳовлилар, турар жой даҳалари автомобил тўхтаб туриш жойлари, ёнилғи қуйиш шахобчалари, корхона ва шунга ўхшашлар).',1),(@qid,'Yo\'llarning o\'zaro bir sathda kesishadigan, tutashadigan va ayriladigan joyi','Место, где дороги пересекаются и разветвляются на одном уровне','Йўлларнинг ўзаро бир сатҳда кесишадиган, туташадиган ва айриладиган жойи',0),(@qid,'Yo\'lning relssiz transport vositalari harakati uchun mo\'ljallangan qismi','Участок дороги, предназначенный для движения безрельсовых транспортных средств','Йўлнинг релссиз транспорт воситалари ҳаракати учун мўлжалланган қисми',0);
