INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'l transport hodisalarining kelib chiqish sabablarini oldini olishga, ularning og\'ir oqibatlarini kamaytirishga qaratilgan faoliyat','Мероприятия, направленные на предупреждение причин дорожно-транспортных происшествий и уменьшение их тяжких последствий','Йўл транспорт ҳодисаларининг келиб чиқиш сабабларини олдини олишга, уларнинг оғир оқибатларини камайтиришга қаратилган фаолият',1),(@qid,'Yo\'llarda harakatni boshqarish bo\'yicha huquqiy, tashkiliy-texnikaviy tadbirlar va boshqaruv harakatlari majmui','Комплекс правовых, конструктивных и технических мероприятий и управленческих мероприятий по организации дорожного движения','Йўлларда ҳаракатни бошқариш бўйича ҳуқуқий, ташкилий-техникавий тадбирлар ва бошқарув ҳаракатлари мажмуи',0),(@qid,'Yo\'l harakati qatnashchilarining yo\'l-transport hodisalari va ularning oqibatlaridan himoyalanganlik darajasini aks ettiruvchi yo\'l harakati holati','Дорожная ситуация, отражающая уровень защищенности участников дорожного движения от дорожно-транспортных происшествий и их последствий','Йўл ҳаракати қатнашчиларининг йўл-транспорт ҳодисалари ва уларнинг оқибатларидан ҳимояланганлик даражасини акс эттирувчи йўл ҳаракати ҳолати',0);
