INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'lning relssiz transport vositalari harakati uchun mo\'ljallangan qismi','Часть дороги, предназначенная для движения нерельсового транспорта','Йўлнинг релссиз транспорт воситалари ҳаракати учун мўлжалланган қисми',0),(@qid,'Avtomobillarning bir qator bo\'lib harakatlanishi uchun etarlicha keng bo\'lgan, yo\'l chiziqlari bilan belgilangan yoki belgilanmagan yo\'l qatnov qismining har qanday bo\'ylama bo\'lagi','Любой продольный участок проезжей части, обозначенный или не обозначенный дорожными линиями, достаточно широкий для движения транспортных средств в один ряд','Автомобилларнинг бир қатор бўлиб ҳаракатланиши учун етарлича кенг бўлган, йўл чизиқлари билан белгиланган ёки белгиланмаган йўл қатнов қисмининг ҳар қандай бўйлама бўлаги',0),(@qid,'Yo\'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to\'xtashi uchun mo\'ljallanmagan, yo\'l sathidan ko\'tarilgan yoki maysazor, ariq, maxsus to\'siqlar bilan ajratilgan baland qismi','Высокий участок дороги, разделяющий расположенные рядом участки движения, не предназначенный для движения или остановки транспортных средств, приподнятый над уровнем дороги или отделенный газоном, канавой, специальным бордюром','Йўлнинг ёнма-ён жойлашган қатнов қисмларини ажратувчи, транспорт воситалари ҳаракатланиши ёки тўхташи учун мўлжалланмаган, йўл сатҳидан кўтарилган ёки майсазор, ариқ, махсус тўсиқлар билан ажратилган баланд қисми',1);
