INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'lning relssiz transport vositalari harakati uchun mo\'ljallangan qismi','Элемент дороги, предназначенный для движения безрельсовых транспортных средств',NULL,0),(@qid,'Yo\'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to\'xtashi uchun mo\'ljallanmagan, yo\'l sathidan baland va (yoki) 1.1 yotiq chizig\'i bilan belgilangan qismi','Элемент дороги, разделяющий смежные проезжие части, не предназначенный для движения или остановки транспортных средств, возвышающийся над уровнем дороги и (или) обозначенный горизонтальной разметкой 1.1',NULL,0),(@qid,'Avtomobillarning bir qator bo\'lib harakatlanishi uchun yetarlicha keng bo\'lgan, yo\'l chiziqlari bilan belgilangan yoki belgilanmagan yo\'l qatnov qismining har qanday bo\'ylama bo\'lagi','Любая из продольных полос проезжей части, обозначенная или не обозначенная разметкой и имеющая ширину, достаточную для движения автомобилей в один ряд',NULL,1);
