INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Qatnov qismi chetidan katta yoshdagilar kuzatuvida olib yurishga ruxsat etiladi','С краю проезжей части в сопровождении взрослых','Қатнов қисми четидан катта ёшдагилар кузатувида олиб юришга рухсат этилади',0),(@qid,'Yo\'l yoqasidan faqat kunduzi va katta yoshdagilar kuzatuvida olib yurishga ruxsat etiladi','По обочинам, только в светлое время суток и в сопровождении взрослых','Йўл ёқасидан фақат кундузи ва катта ёшдагилар кузатувида олиб юришга рухсат этилади',1);
