INSERT INTO `Options` (`QuestionId`,`OptionUZ`,`OptionRU`,`OptionUZK`,`IsCorrect`) VALUES (@qid,'Yo\'llarning qatnov qismlari o\'zaro kesishib o\'tadigan va tasavvur qilinadigan chiziqlar bilan aniqlangan hudud','Территория, на которой пересекаются проезжие части дорог, ограниченная воображаемыми линиями',NULL,1),(@qid,'Yo\'llarning o\'zaro bir sathda kesishadigan, tutashadigan va ayriladigan joyi','Место пересечения, примыкания или разветвления дорог на одном уровне',NULL,0),(@qid,'Yo\'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to\'xtashi uchun mo\'ljallanmagan, yo\'l sathidan ko\'tarilgan yoki maysazor, ariq, maxsus to\'siqlar bilan ajratilgan baland qismi','Элемент дороги, разделяющий смежные проезжие части, не предназначенный для движения или остановки транспортных средств, приподнятый над уровнем дороги или отделённый газоном, арыком, специальными ограждениями',NULL,0);
